INSERT INTO `main_film` VALUES (1, '星际穿越', '克里斯托弗·诺兰', '马修·麦康纳, 安妮·海瑟薇, 杰西卡·查斯坦', '2014-11-07', '在不久的将来，地球面临着严重的环境危机，粮食短缺威胁着人类的生存。前NASA宇航员库珀（马修·麦康纳饰）被神秘的重力异常现象引导，发现了一个秘密的NASA基地，并加入了一个拯救人类的计划。', '/static/posters/星际穿越_medium.jpg', 3, 6, NULL, NULL, '2025-10-28 10:47:21', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (2, '盗梦空间', '克里斯托弗·诺兰', '莱昂纳多·迪卡普里奥, 约瑟夫·高登-莱维特, 艾伦·佩吉', '2010-07-16', '多姆·科布（莱昂纳多·迪卡普里奥饰）是一位经验丰富的窃贼，他在人们精神最为脆弱的梦境中活动，窃取潜意识中有价值的信息。', '/static/posters/盗梦空间_medium.jpg', 1.5, 2, NULL, NULL, '2025-10-28 10:47:21', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (4, '阿甘正传', '罗伯特·泽米吉斯', '汤姆·汉克斯, 罗宾·怀特, 加里·西尼斯', '1994-07-06', '阿甘（汤姆·汉克斯饰）是一个智商只有75的低能儿，但他的母亲总是鼓励他"傻人有傻福"，要他自强不息。阿甘像普通孩子一样上学，并且认识了一生的朋友和至爱珍妮。', '/static/posters/阿甘正传_medium.jpg', 2.3, 6, NULL, NULL, '2025-10-28 10:47:21', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (5, '泰坦尼克号', '詹姆斯·卡梅隆', '莱昂纳多·迪卡普里奥, 凯特·温丝莱特', '1997-12-19', '1912年4月10日，号称"世界工业史上的奇迹"的豪华客轮泰坦尼克号开始了自己的处女航，从英国的南安普顿出发驶往美国纽约。富家少女露丝（凯特·温丝莱特饰）与母亲及未婚夫卡尔坐上了头等舱。', '/static/posters/泰坦尼克号_medium.jpg', 3, 3, NULL, NULL, '2025-10-28 10:47:21', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (6, '星际穿越', '克里斯托弗·诺兰', '马修·麦康纳, 安妮·海瑟薇, 杰西卡·查斯坦', '2014-11-07', '在不久的将来，地球面临着严重的环境危机，粮食短缺威胁着人类的生存。前NASA宇航员库珀（马修·麦康纳饰）被神秘的重力异常现象引导，发现了一个秘密的NASA基地，并加入了一个拯救人类的计划。', '/static/posters/星际穿越_medium.jpg', 2.2, 5, NULL, NULL, '2025-10-28 10:47:58', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (7, '盗梦空间', '克里斯托弗·诺兰', '莱昂纳多·迪卡普里奥, 约瑟夫·高登-莱维特, 艾伦·佩吉', '2010-07-16', '多姆·科布（莱昂纳多·迪卡普里奥饰）是一位经验丰富的窃贼，他在人们精神最为脆弱的梦境中活动，窃取潜意识中有价值的信息。', '/static/posters/盗梦空间_medium.jpg', 3, 2, NULL, NULL, '2025-10-28 10:47:58', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (8, '肖申克的救赎', '弗兰克·德拉邦特', '蒂姆·罗宾斯, 摩根·弗里曼', '1994-09-23', '银行家安迪（蒂姆·罗宾斯饰）被冤枉杀害了他的妻子及其情人，被判处无期徒刑，关在肖申克监狱里。在狱中，他结识了"瑞德"（摩根·弗里曼饰），并在监狱中度过了长达19年的时光。', '/static/posters/肖申克的救赎_medium.jpg', 2.4, 8, NULL, NULL, '2025-10-28 10:47:58', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (11, '是我们的错', '多明戈·冈萨雷斯', '妮科莱·瓦利亚塞, 加布里埃尔·格瓦拉, 加布里埃拉·安德拉达, 玛塔·哈扎斯, 戈雅·托莱多', '2025-10-15', '尼克和诺亚的关系正处于最美好的时刻。然而，这对恋人似乎再也无法回到从前。一系列事件将接踵而至，让他们最终明白彼此是否真正适合对方。或者，相反地，他们会发现最好的选择是分道扬镳，即便要忘记如此深刻的爱或抹去烙印在心上的记忆是那么困难。爱并非总是足够，而原谅有时也不足以修复一切。他们能否放下过去，重新开始呢？', '/static/posters/是我们的错_medium.jpg', 3.7, 6, 1156594, 7.637, '2025-10-28 11:06:47', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (12, '余烬夺宝', 'J.J.佩里', '戴夫·巴蒂斯塔, 欧嘉·柯瑞兰寇, 克里斯托弗·海维尤, 塞缪尔·杰克逊, 丹尼尔·伯恩哈特', '2025-08-20', '在一场巨大的太阳耀斑摧毁了地球东半球之后，一名大胆的寻宝者受雇前往欧洲去寻找《蒙娜丽莎》，却发现这个世界更需要的是英雄，而非一幅画。', NULL, 4.5, 2, 507244, 6.282, '2025-10-28 11:13:15', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (13, '狩猎场', 'Derek Barnes', '埃米莉·阿拉塔洛, Tim Rozon, 帕特里克·加罗, Jon McLaren, Milton Barnes', '2025-05-16', '克洛伊·马维诺为了给孩子们寻找庇护，不顾一切地逃离了与黑手党有染的丈夫，在一个名叫杰克的隐居流浪汉家的小屋里找到了栖身之所。然而，随着丈夫的追随者们逐渐逼近她，她发现杰克才是他们最大的敌人。', '/static/posters/狩猎场_medium.jpg', 6.293, 41, 1305717, 6.293, '2025-10-28 11:13:15', '2025-10-28 11:19:52');
INSERT INTO `main_film` VALUES (14, '世界大战', 'Rich Lee', '艾斯·库珀, 伊娃·朗格里亚, 克拉克·格雷格, Iman Benson, Henry Hunter Hall', '2025-07-29', '威尔·拉德福德是国土安全部的顶级网络安全分析师，他通过大规模监控项目追踪国家安全的潜在威胁。直到有一天，一个不明实体的攻击让他开始怀疑政府是否对他……以及世界其他地方隐瞒了什么。', NULL, 3, 1, 755898, 4.3, '2025-10-28 11:13:15', '2025-10-28 11:59:35');
INSERT INTO `main_film` VALUES (15, '虎克船长：诅咒潮汐', 'Lars Janssen', 'Sean Cronin, Ewen Weatherburn, Cameron Ashplant, Richard Rowden, Destiny Viva', '2025-07-11', '', '/static/posters/虎克船长：诅咒潮汐_medium.jpg', 2.6, 5, 1511789, 4.893, '2025-10-28 11:13:16', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (16, '鬼灭之刃剧场版：无限城篇Part.1', '外崎春雄', '花江夏树, 下野纮, 樱井孝宏, 石田彰, 松冈祯丞', '2025-07-18', '当鬼杀队的成员和柱之人在为即将到来的与鬼的战斗做准备，完成共同的体能训练——柱之训练时，鬼舞辻无惨在产屋敷宅邸出现。由于鬼杀队的主公处于危险之中，炭治郎和柱急忙赶往总部，但却被鸣女推入一个神秘的异空间。炭治郎和鬼杀队的目标是鬼的堡垒——无限城。因此，鬼杀队和鬼之间的最终战斗的战场已经准备就绪。', NULL, 3, 4, 1311031, 7.801, '2025-10-28 11:13:16', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (17, '长生血战', 'Kimo Stamboel', 'Mikha Tambayong, 伊娃·西莉亚, Marthino Lio, Dimas Anggara, Varen Arianda Calief', '2025-10-22', '一个关系不和的家庭经营着一家知名的草药公司。公司老板试图创新，研制一种新药水，结果却引发了丧尸疫情。', NULL, 4, 1, 1306525, 5.57, '2025-10-28 11:13:17', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (18, '急转直下', 'James Kent', '凯特·贝金赛尔, 斯科特·伊斯特伍德, Arvin Kananian, 马特·克拉文, Ana Golja', '2025-09-04', '', '/static/posters/急转直下_medium.jpg', 2.3, 3, 1280450, 6.337, '2025-10-28 11:13:17', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (19, '死亡竞走', '弗朗西斯·劳伦斯', '库珀·霍夫曼, 戴维·荣松, Garrett Wareing, 屠特·尼约特‌, 查理·普卢默', '2025-09-10', '在一个未来的反乌托邦社会中，政府举办的残酷的死亡游戏——"死亡竞走"。这是一场没有终点的竞走比赛，参赛者是100名被挑选出来的年轻人。任何落后或走不动的人，会在三次警告后被立即处决，直到剩下最后一个。', '/static/posters/死亡竞走_medium.jpg', 2.3, 3, 604079, 6.856, '2025-10-28 11:13:17', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (20, '喋血杀机', 'A. P. Arjun', 'Dhruva Sarja, Vaibhavi Shandilya, Anveshi Jain, Giorgia Andriani, Chikkanna', '2024-10-11', '影片主角马丁，一位神秘而勇敢的人物，在充满未知的世界中展开了一场惊心动魄的冒险。马丁不知因何原因陷入了一个复杂的困境之中，他一方面努力探寻自己的真实身份，试图解开过去的谜团。另一方面，他发现自己身处的世界暗流涌动，国内的黑市商人与恐怖分子相互勾结，谋划着一场足以给国家带来巨大灾难的大规模袭击。马丁毅然决然地踏上了阻止这场阴谋的征程。', NULL, 4, 2, 861451, 3.1, '2025-10-28 11:13:18', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (21, '炸裂白宫', '凯瑟琳·毕格罗', '伊德瑞斯·艾尔巴, 丽贝卡·弗格森, 加布里埃尔·巴索, 杰瑞德·哈里斯, 崔西·莱茨', '2025-10-02', '来源不明的一颗导弹朝着美国发射，谁该负责？又该如何应对？一场分秒必争的角力就此展开。', NULL, 3, 5, 1290159, 6.396, '2025-10-28 11:13:18', '2025-10-28 11:59:43');
INSERT INTO `main_film` VALUES (22, '招魂4：终章', '迈克尔·查韦斯', '维拉·法米加, 帕特里克·威尔森, 米娅·汤姆林森, 本·哈迪, Rebecca Calder', '2025-09-03', '故事设定在1986年，即《招魂3》的五年后。沃伦夫妇因艾德在第三部中经历恶灵事件而突发心脏病，已正式退休，不再从事驱魔工作。他们仍会到大学巡回演讲，但连这类机会也在逐渐减少。一些事件最终还是让他们重返战场。这次的核心案件，是沃伦夫妇生涯中最著名的一起事件之一：斯莫尔家族闹鬼案。', NULL, 5, 1, 1038392, 6.993, '2025-10-28 11:13:19', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (23, '重返虎穴2', 'Cyprian T. Olencki', '马特兹·达米克基, Szymon Bobrowski, Pola Gonciarz, Weronika Książkiewicz-Nathaniel, Łukasz Simlat', '2025-10-14', '厮杀过后，狂怒帮的新头目阿金开始统领这支残暴又强大的黑帮，并将目标转向了境外。', NULL, 6.51, 50, 1072699, 6.51, '2025-10-28 11:13:19', '2025-10-28 11:13:19');
INSERT INTO `main_film` VALUES (24, '夺命小丑2', 'Colin Krawchuk', 'Michael Sheffield, Kaitlyn Trentham, Dingani Beza, Hassen Kacem, Jessica Ambuehl', '2025-09-15', '', '/static/posters/夺命小丑2_medium.jpg', 3.2, 5, 1519168, 6.7, '2025-10-28 11:13:19', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (25, '黑色电话2', '斯科特·德里克森', '伊桑·霍克, 梅森·泰晤士, 玛德琳·麦格劳, 德米安·比齐尔, 米格尔·莫拉', '2025-10-15', '布伦屋热门恐怖片《黑色电话》续集《黑色电话2》定档2025年6月27日北美上映，阵容和剧情暂未曝光。', '/static/posters/黑色电话2_medium.jpg', 1.8, 5, 1197137, 7.106, '2025-10-28 11:13:20', '2025-10-28 12:05:36');
INSERT INTO `main_film` VALUES (26, '我的过错', '多明戈·冈萨雷斯', '妮科莱·瓦利亚塞, 加布里埃尔·格瓦拉, 玛塔·哈扎斯, 伊万·桑切斯, 艾娃·鲁伊斯', '2023-06-08', '诺亚被迫离开她的小镇、男友和朋友，搬进了她母亲的新丈夫的豪宅。在那里，她遇见了她的新继兄尼克，两人的性格从一开始就发生了碰撞。然而他们对彼此的吸引却渐渐演变成一段禁忌的恋情，在这期间，他们叛逆的性格和磨人的脾气颠覆了彼此的世界，并致使他们疯狂地坠入了爱河。', NULL, 3.5, 2, 1010581, 7.769, '2025-10-28 11:13:20', '2025-10-28 11:59:43');
INSERT INTO `main_film` VALUES (27, '神奇四侠：初露锋芒', '麦特·夏克曼', '佩德罗·帕斯卡, 凡妮莎•柯比, 爱波·莫斯-巴克拉赫, 约瑟夫·奎恩, 拉尔夫·伊内森', '2025-07-23', '神奇先生、隐形女、霹雳火和石头人面对来自宇宙级威胁"行星吞噬者"及其使者"银影侠"对地球上所有生灵的威胁，四人必须在家庭羁绊与英雄使命间抉择，挺身而出接受这个前所未有的严峻挑战。更令人措手不及的是，这场关乎地球存亡的危机竟与他们有着意想不到的关联。', NULL, 3.2, 4, 617126, 7.1, '2025-10-28 11:13:20', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (28, '电锯人 - 剧场版：蕾塞篇', '吉原达矢', '户谷菊之介, 上田丽奈, 井泽诗织, 楠木灯, 坂田将吾', '2025-09-19', '', NULL, 3, 4, 1218925, 8.073, '2025-10-28 11:13:21', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (29, '极限特工', '罗伯·科恩', '范·迪塞尔, 艾莎·阿基多, 马尔顿·索克斯, 塞缪尔·杰克逊, 迈克尔·鲁夫', '2002-08-09', '克桑德是极限运动界的明星，但他离经叛道，总是以他的身手对社会上那些败类名流发出挑战，当地警方对他也经常无可奈何。特工头子奥古斯塔斯看上了克桑德，于是派人将他抓了回来，说服他前往捷克进行一项危险而艰巨的任务。', NULL, 5, 1, 7451, 6, '2025-10-28 11:13:21', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (30, 'K-POP：猎魔女团', 'Chris Appelhans, Maggie Kang', '赵雅顿, 梅·洪, 柳智英, 安孝燮, 金允珍', '2025-06-20', 'K-pop 超级明星鲁米、米拉和佐伊如果不是在座无虚席的体育场举办演唱会，就是在利用自己的秘密力量保护粉丝们免受超自然威胁。', NULL, 3, 1, 803796, 8.232, '2025-10-28 11:13:22', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (31, '毒魔复仇', '梅肯·布莱尔', '彼特·丁拉基, 雅各布·特伦布莱, 泰勒·佩姬, 朱莉娅·戴维斯, Jonny Coyne', '2025-08-28', '一场可怕的有毒物质事故，将饱受压迫的门卫温斯顿・古兹改造成了一位全新的进化型英雄："毒魔侠"！如今，他手握一把散发着荧光、拥有超人力量的拖把，必须争分夺秒拯救自己的儿子，并阻止一位冷酷无情、贪权成性的暴君 —— 此人正企图利用有毒超能力巩固他那充斥着污染的帝国。', '/static/posters/毒魔复仇_medium.jpg', 2, 4, 338969, 6.342, '2025-10-28 11:13:24', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (32, '神圣之夜：恶魔猎人', 'Lim Dae-hee', '马东锡, 徐贤, 李大卫, 庆收真, 郑知苏', '2025-04-30', '影片讲述狩猎恶魔的黑暗解决师"神圣之夜"团队与崇拜邪恶的犯罪集团对抗的故事。', '/static/posters/神圣之夜：恶魔猎人_medium.jpg', 6.712, 60, 793387, 6.712, '2025-10-28 11:13:24', '2025-10-28 11:19:42');
INSERT INTO `main_film` VALUES (33, '你的过错', '多明戈·冈萨雷斯', '妮科莱·瓦利亚塞, 加布里埃尔·格瓦拉, 玛塔·哈扎斯, 伊万·桑切斯, 艾娃·鲁伊斯', '2024-12-26', '全球热播电影《我的过错》续篇。尽管诺亚和尼克的父母试图拆散他们，但他们的关系似乎毫不动摇。然而他的工作和她的大学入学却给他们原本的生活带来了新的人际关系，眼看就要动摇他们的感情和莱斯特家族的根基。面对这么多蓄意破坏的人，这段感情真的能迎来圆满的结局吗？', '/static/posters/你的过错_medium.jpg', 3.5, 2, 1156593, 7.143, '2025-10-28 11:13:25', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (34, '推动摇篮的手', 'Michelle Garza Cervera', '麦卡·梦露, 玛丽·伊丽莎白·温斯特德, 劳尔·卡斯蒂略, Mileiah Vega, Nora Contreras', '2025-10-21', '影片翻拍自1992年的同名恐怖片。Caitlin（玛丽·伊丽莎白·温斯特德 Mary Elizabeth Winstead 饰） 聘请到一位似乎完美的新保姆 Polly（麦卡·梦露 Maika Monroe 饰）以为从此可以安心，殊不知保姆暗藏心机……一切幸福，原来只是噩梦的开始。', NULL, 4, 5, 1362315, 5.706, '2025-10-28 11:13:25', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (35, '异星迷航', 'Jess Varley', '凯特·玛拉, 劳伦斯·菲什伯恩, 加布里埃尔·鲁纳, 伊万娜·米利塞维奇, Macy Gray', '2025-09-26', '宇航员萨姆·沃克在完成自己第一次太空任务后重返地球的途中不幸坠入大西洋深海。尽管航天局派出许多救援队进行了长时间的救援后仍未找到萨姆。就在众人准备撤退放弃时，萨姆却奇迹般地出现，幸存了下来。萨姆的这次经历实在让人难以置信。航天局虽然准许她回到家里跟丈夫团聚，但是却受到了NASA的严密监视以及威廉·哈里斯将军的控制，开始在一座戒备森严的屋子里完成康复和医学检测。当周围接二连三发生了令人不安的事件时，她开始怀疑有外星人跟自己回到了地球。', '/static/posters/异星迷航_medium.jpg', 4.5, 2, 1086260, 5.781, '2025-10-28 11:13:25', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (36, '消失的公主', 'Hicham Hajji', '基利安·奥沙利文, 加里·杜尔丹, 罗伯特·克内珀, Soraya Azzabi, 埃里克·罗伯茨', '2025-10-16', '', '/static/posters/消失的公主_medium.jpg', 5, 1, 1086910, 6.3, '2025-10-28 11:13:26', '2025-10-28 11:59:41');
INSERT INTO `main_film` VALUES (37, '玫瑰', '杰伊·罗奇', '奥利维娅·科尔曼, 本尼迪克特·康伯巴奇, 凯特·麦金农, 安迪·萨姆伯格, 舒提·盖特瓦', '2025-08-27', '艾薇（奥利维娅·科尔曼 Olivia Colman 饰）和西奥（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）是一对表面幸福、实则危机四伏的中产夫妻。 他们有钱、有貌、有小孩，人生完美无死角……直到现实开始崩坏。 他失势、她崛起；爱情不再对等，成就变成武器，婚姻成了战场。 当爱不再是羁绊，而是竞争，家不再安全而是战场，你该如何处理枕边人。', '/static/posters/玫瑰_medium.jpg', 3, 4, 1267905, 6.9, '2025-10-28 11:13:26', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (38, 'Falcon Express', 'Benoît Daffis, Jean-Christian Tassy', 'Damien Ferrette, Hervé Jolly, Kaycie Chase, Frantz Confiac, Emmanuel Garijo', '2025-07-02', '', '/static/posters/Falcon_Express_medium.jpg', 3, 4, 1107216, 7, '2025-10-28 11:13:26', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (39, '逆途', 'Haneef Adeni', 'Unni Mukundan, 西迪克, Ishan Shoukath, Jagadish, Abhimanyu Thilakan', '2024-12-20', '影片以主角 Marco 的视角展开，他曾误入歧途成为黑帮成员，但内心深处一直保留着善良的本质。故事中，Marco 所在的城市出现了一系列危害社会安全的恶性事件，警方在调查过程中发现这些事件与黑帮的非法活动有千丝万缕的联系。Marco 在经历了一些事情后，开始反思自己的生活和选择。当他发现黑帮的阴谋可能会给城市里无辜的人们带来巨大灾难时，他决定挺身而出。', '/static/posters/逆途_medium.jpg', 5, 1, 1186350, 6.609, '2025-10-28 11:13:27', '2025-10-28 12:05:36');
INSERT INTO `main_film` VALUES (40, 'Butchers Book Two: Raghorn', 'Adrian Langley', 'Nick Biskupek, Michael Swatton, Sam Huntsman, Hollie Kennedy, Corgand Janeway-Svendsen', '2024-02-29', '', '/static/posters/Butchers_Book_Two__Raghorn_medium.jpg', 2.7, 6, 1244039, 3.4, '2025-10-28 11:13:27', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (41, '陌生人：第二章', '雷尼·哈林', '玛德莱娜·佩切, Froy Gutierrez, 加布里埃尔·巴索, 艾玛·霍瓦特, Brooke Lena Johnson', '2025-09-25', '当《陌生人》得知他们的受害者之一玛雅尚在人世，便再度归来，要将未竟之事斩草除根。', '/static/posters/陌生人：第二章_medium.jpg', 3.3, 7, 1010756, 5.825, '2025-10-28 11:13:27', '2025-10-28 12:05:46');
INSERT INTO `main_film` VALUES (42, 'Tide', 'Berty Cadilhac', 'Alice Sanders, Edmund C. Short, Benjamin McMahon, Isabella Colby Browne, Kevin Sionneau', '2024-09-12', '', '/static/posters/Tide_medium.jpg', 3, 2, 1291661, 3.8, '2025-10-28 11:13:28', '2025-10-28 11:59:39');
INSERT INTO `main_film` VALUES (43, '脏局', '肖恩·布莱克', '马克·沃尔伯格, 拉基思·斯坦菲尔德, 罗莎·萨拉查, 科甘-迈克尔·凯, 楚克武迪·武吉', '2025-09-30', '在沙恩·布莱克执导的动作惊悚片《脏局》中，职业大盗帕克与格罗菲尔德、善及一众身怀绝技的同伙，精心策划了盗贼生涯中最大的一票，却因一笔横财意外卷入了与纽约黑帮的生死博弈。', '/static/posters/脏局_medium.jpg', 5, 1, 941109, 6.65, '2025-10-28 11:13:28', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (44, 'Ur mörkret', 'Philip W. da Silva', 'Rakel Benér, Oscar Skagerberg, Peter Mörlin, Thomas Hedengran, Amanda Kilpeläinen Arvidsson', '2024-03-22', '', '/static/posters/Ur_mörkret_medium.jpg', 3, 3, 1202863, 6.3, '2025-10-28 11:13:28', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (45, '黑霉', 'John Pata', 'Agnes Albright, Jeremy Holm, Maisie Merlock, Caito Aase, Andrew Bailes', '2025-01-30', '', '/static/posters/黑霉_medium.jpg', 3, 2, 949855, 4, '2025-10-28 11:13:29', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (46, '碟中谍8：最终清算', '克里斯托弗·麦夸里', '汤姆·克鲁斯, 海莉·阿特维尔, 文·瑞姆斯, 西蒙·佩吉, 埃赛·莫拉莱斯', '2025-05-17', '超级人工智能"智体"即将引爆全球核弹危机，把世界推向毁灭边缘。而伊森·亨特和他的IMF小队在上次行动中遭遇重创，团队濒临分崩离析。虽然伊森已获得关闭"智体"的钥匙，但要彻底消灭"智体"，完成这一拯救全人类的终极任务，仍需要IMF小队齐心协力突破重重困难。', '/static/posters/碟中谍8：最终清算_medium.jpg', 1, 1, 575265, 7.278, '2025-10-28 11:13:29', '2025-10-28 12:05:46');
INSERT INTO `main_film` VALUES (47, '超人', '詹姆斯·古恩', '大卫·科伦斯韦特, 瑞秋·布罗斯纳安, 尼古拉斯·霍尔特, 艾迪·盖瑟吉, 内森·菲利安', '2025-07-09', '当超人（大卫·科伦斯韦 饰）被卷入国内外多重冲突时，他保护人类的行为遭到质疑。而他显露的弱点，也趁机被科技巨擘、阴谋大师莱克斯·卢瑟（尼古拉斯·霍尔特 饰）利用，准备一举铲除超人。《星球日报》勇敢无畏的记者露易丝·莱恩（瑞秋·布罗斯纳安 饰）能否联手大都会的其他超能力者，以及超人忠诚的伙伴超狗小氪，在卢瑟彻底毁灭超人前拯救他？', '/static/posters/超人_medium.jpg', 2.4, 5, 1061474, 7.4, '2025-10-28 11:13:30', '2025-10-28 12:05:46');
INSERT INTO `main_film` VALUES (48, '蠢特夫妇', '菲尔·约翰斯顿', '玛戈·马丁代尔, Johnny Vegas, 麦特里伊·拉玛克里斯南, Ryan Anderson Lopez, 艾米莉亚·克拉克', '2025-10-17', '改编自罗尔德·达尔的同名儿童小说，蠢特夫妇是世界上最卑鄙、恶臭、下流的人，他们恰巧经营着世上最恶心、危险、愚蠢的游乐园Twitlandia。当他们在生活的城镇崛起掌权时，两个勇敢的孤儿和一群神奇的动物挺身而出，被迫变得像蠢特夫妇一样狡猾，以拯救这座城市。', '/static/posters/蠢特夫妇_medium.jpg', 3.5, 2, 927254, 6.6, '2025-10-28 11:13:30', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (49, '凶器', '扎克·克雷格', '朱莉亚·加德纳, 乔什·布洛林, 奥尔登·埃伦赖希, 奥斯汀·艾布拉姆斯, 王汉斌', '2025-08-04', '同一个班上除了一名孩子外，其余所有孩子在同一天晚上的同一时间神秘失踪，这让整个社区开始怀疑究竟是谁或什么导致了他们的失踪。', '/static/posters/凶器_medium.jpg', 3, 1, 1078605, 7.359, '2025-10-28 11:13:30', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (50, '宝莱坞双雄之战2', '阿扬·慕克吉', '小N·T·拉玛·拉奥, 李提克·罗森, 伽罗·阿德瓦尼, 阿舒托史.拉纳, 亚尼·卡普', '2025-08-13', '佣兵卡毕尔接下风险奇高的任务，替犯罪组织卖命，却随即发现自己和无所畏惧的过往盟友反目为敌。', '/static/posters/宝莱坞双雄之战2_medium.jpg', 3.8, 4, 1109086, 5.351, '2025-10-28 11:13:31', '2025-10-28 12:05:35');
INSERT INTO `main_film` VALUES (51, '二十七个夜晚', 'Daniel Hendler', 'Marilú Marini, Daniel Hendler, Humberto Tortonese, 朱丽叶塔·齐尔伯伯格, Paula Grinszpan', '2025-09-19', '一名女子因行事不羁被女儿们送去精神病诊所，一位专家必须判断她是病了，还是只是想享受生活。', '/static/posters/二十七个夜晚_medium.jpg', 4, 2, 1327769, 6.2, '2025-10-28 11:13:33', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (52, '潘神的迷宫', '吉尔莫·德尔·托罗', '伊万娜·巴克罗, 塞尔希·洛佩斯, 玛丽贝尔·韦尔杜, 艾妮安娜·姬儿, 道格·琼斯', '2006-10-11', '12岁女孩子奥菲丽娅（伊万娜•巴克尔洛 饰）有一个凶暴的法西斯军官继父维达（塞吉•洛佩兹 饰），他的任务就是镇压反抗者，研究各种刑具来折磨残害被抓来的异见人士，奥菲丽娅每天都目睹让人不愉快的事件。眼看着冷酷的继父和其党羽每日作恶还以此为乐，母亲又身怀六甲患病在床，被孤独感和目睹暴行的痛苦困扰的奥菲丽娅开始沉浸在自己的幻想中聊以自慰。', '/static/posters/潘神的迷宫_medium.jpg', 2.3, 6, 1417, 7.8, '2025-10-28 11:13:33', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (53, '为你遗憾', '乔什·布恩', '麦肯娜·格瑞丝, 艾莉森·威廉姆斯, 戴夫·弗兰科, 梅森·泰晤士, 薇拉·菲茨杰拉德', '2025-10-22', '一宗牵涉两条人命的严重交通意外，揭开了令人震惊的秘密；一对母女被迫面对家族的伤痕，探索爱的定义，并重新认识彼此。影片改编自《爱情，到此为止》原作者科琳·胡佛的同名畅销小说。', '/static/posters/为你遗憾_medium.jpg', 3.5, 2, 1327862, 7.192, '2025-10-28 11:13:33', '2025-10-28 12:05:35');
INSERT INTO `main_film` VALUES (54, '侏罗纪世界：重生', '加里斯·爱德华斯', '斯嘉丽·约翰逊, 马赫沙拉·阿里, 乔纳森·贝利, 鲁珀特·弗兰德, 马奴·贾西亚·鲁尔福', '2025-07-01', '地球生态已被证明广泛不适合恐龙生存，危在旦夕的恐龙族群生存于孤岛之上，但是它们中却隐藏着能够带来人类医药奇迹的关键基因，为获取神秘基因，一支精英小队潜入恐龙禁地，然而等待他们的却是无法预知的危机和惊天阴谋……', '/static/posters/侏罗纪世界：重生_medium.jpg', 4, 2, 1234821, 6.4, '2025-10-28 11:13:34', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (55, '创：战神', '乔阿吉姆·罗恩尼', '杰瑞德·莱托, 格蕾塔·李, 埃文·彼得斯, 吉莲·安德森, 茱蒂·透納-史密斯', '2025-10-08', '"战神"阿瑞斯（Ares）这个来自数字世界的高度人工智能体，被派遣至现实世界执行高危任务，他的行动将引发人类与人工智能体的首次正面相遇。', '/static/posters/创：战神_medium.jpg', 3, 6, 533533, 6.37, '2025-10-28 11:13:34', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (56, '攻击鬼魂13号', 'Taweewat Wantha', 'กรณิศ เล้าสุบินประเสริฐ, ณิชภาลักษณ์ ทองคำ, เพิร์ธ วีริณฐ์ศรา ตั้งกิจสุวานิช, Nuttawatt Thanathaveeprasert, Tarisa Preechatangkit', '2025-06-13', '欺负人是不好，可是如果从你活着的时候就欺负你，直到你死了变成鬼，还不停的欺负你……被欺负到死，他们还怎么活下去？', '/static/posters/攻击鬼魂13号_medium.jpg', 2, 2, 1419027, 6.5, '2025-10-28 11:13:34', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (57, '原始战争', 'Luke Sparke', '傑瑞米·皮文, 翠西亚·希弗, 瑞恩·柯万腾, Nick Wechsler, Anthony Ingruber', '2025-08-21', '越战期间，一支侦察小队潜入与世隔绝的丛林山谷，调查失踪步兵排的下落。他们很快发现自己不得不为生存而战，而对手竟是意想不到的敌人——史前恐龙。', '/static/posters/原始战争_medium.jpg', 2, 6, 1257009, 6.8, '2025-10-28 11:13:35', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (58, '铁拳怒潮', '路易斯·曼迪勒', '斯科特·阿金斯, 彼得·辛科达, 迈克尔·科彭, Donald Cerrone, Michael Rene Walton', '2025-09-19', '', '/static/posters/铁拳怒潮_medium.jpg', 3.5, 2, 1328803, 7, '2025-10-28 11:13:35', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (59, '鬼妈', 'ไพรัช คุ้มวัน', 'ธิติยา จิระพรศิลป์, เพิร์ธ วีริณฐ์ศรา ตั้งกิจสุวานิช, พิสิฐพล เอกพงศ์พิสิฐ, Narinthorn Na Bangchang, Weeraya Zhang', '2025-10-09', '', '/static/posters/鬼妈_medium.jpg', 5.857, 7, 1535290, 5.857, '2025-10-28 11:13:36', '2025-10-28 11:19:02');
INSERT INTO `main_film` VALUES (60, '骨湖', 'Mercedes Bryce Morgan', '麦蒂·哈森, 亚历克斯·罗伊, Marco Pigossi, Andra Nechita, Eliane Reis', '2025-10-02', '一对情侣在僻静的湖畔庄园享受浪漫假期，却因被迫与一对神秘又迷人的情侣共用这栋豪宅而彻底被打乱。在这个充满暗黑幽默和情色诱惑的恐怖故事中，一场梦幻之旅逐渐陷入充斥着欲望、谎言与操控的噩梦迷宫——不仅骇人的秘密被层层揭开，更引发了一场血雨腥风的生存之战。', '/static/posters/骨湖_medium.jpg', 2.2, 6, 1330421, 5.667, '2025-10-28 11:13:36', '2025-10-28 12:05:39');
INSERT INTO `main_film` VALUES (61, '新·驯龙高手', '迪恩·德布洛斯', '梅森·泰晤士, 妮可·帕克, 杰拉德·巴特勒, 尼克·弗罗斯特, 加布里埃尔·豪尔', '2025-06-06', '小嗝嗝（梅森·泰晤士 Mason Thames 饰 ）偶然间遭遇传说中的夜煞没牙仔，并由此与之建立深厚友谊，进而打破两大族群间的隔阂，携手寻求和平。', '/static/posters/新·驯龙高手_medium.jpg', 8.012, 2095, 1087192, 8.012, '2025-10-28 11:13:36', '2025-10-28 11:19:04');
INSERT INTO `main_film` VALUES (62, '羊魔杀', 'Steve Wolsh', 'Arielle Raycene, Ellie Gonsalves, 凯恩·霍德, Danielle Mathers, Monica Sims', '2023-04-28', '奥德拉的毕业礼物是她的梦想之屋，但它很快就变成了一场活生生的噩梦，因为一些不请自来的客人来到了她的返校聚会，他们并没有很含蓄地表示不同意这个房子的新主人。', '/static/posters/羊魔杀_medium.jpg', 3.2, 5, 1073079, 2.636, '2025-10-28 11:13:37', '2025-10-28 12:05:35');
INSERT INTO `main_film` VALUES (63, '黑色电话', '斯科特·德里克森', '梅森·泰晤士, 玛德琳·麦格劳, 伊桑·霍克, 杰瑞米·戴维斯, E·罗杰·米切尔', '2022-06-16', '本片根据乔·希尔同名短篇小说改编：1978年间美国科罗拉多州一处郊外小镇里，一位名为芬尼·萧的少年被绰号为"掳童犯"的杀手绑架，而此前已有五位孩童被后者绑架杀害。芬尼之后在囚禁他的地下室中发现一部古董电话，尽管电话线已经断了，但一到晚上，他总能接到来自过去受害者试图帮助他的来电；芬尼的妹妹格温也在此时梦到与之相关的异象，指引她寻找芬尼。发生在兄妹俩身上的灵异事件开始成为了拯救芬尼的关键。', '/static/posters/黑色电话_medium.jpg', 3, 2, 756999, 7.551, '2025-10-28 11:13:37', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (64, '勇敢之人', 'Steve Barnett', 'Chase Stokes, 拉娜·孔多尔, 德斯敏·博尔赫斯, 卡兰·马尔韦, Diana Tsoy', '2025-01-30', '随着朝鲜和韩国之间的紧张局势，一架美国直升机在朝鲜一侧坠毁，现在幸存者必须共同努力保护一名民用技术专家，并在没有美国军事支持的情况下找到出路。', '/static/posters/勇敢之人_medium.jpg', 3.3, 3, 1009640, 6.619, '2025-10-28 11:13:37', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (65, 'Revival', 'Dario Germani', '路易斯·曼迪勒, 迈克尔·帕雷, Yonv Joseph, Nathalie Rapti Gomez, James Chalke', '2024-11-28', '', '/static/posters/Revival_medium.jpg', 1, 3, 1383557, 5, '2025-10-28 11:13:38', '2025-10-28 12:05:37');
INSERT INTO `main_film` VALUES (66, '杀手螳螂', '이태성', '任时完, 朴珪瑛, 崔显旭, 裴江熙, 黄成彬', '2025-09-26', 'A级王牌杀手螳螂长期休假后回归，试图挖角他的杀手们蜂拥而至，当他重新踏入这个无秩序世界时，他向既是老友又是竞争对手的在伊提议，以自己的名字成立一家能超越MK的公司，螳螂昔日的师父，也是已经退休的传奇杀手独孤则接手了MK娱乐成了新代表，他向螳螂警告在伊并不是个好搭档，三人表面上看似友好，实际上却展开激烈的争斗，究竟谁才能成为暗黑世界的新主宰？', '/static/posters/杀手螳螂_medium.jpg', 3, 3, 1267319, 6.038, '2025-10-28 11:13:38', '2025-10-28 12:05:46');
INSERT INTO `main_film` VALUES (67, '10号舱里的女人', 'Simon Stone', '凯拉·奈特莉, 盖·皮尔斯, 大卫·阿贾拉, Gitte Witt, 阿特·马里克', '2025-10-09', '改编自露丝·韦尔的同名畅销小说。一名旅游记者被派去报道一艘豪华游艇的下水仪式，她在夜深人静时目睹一名乘客被抛入海中，但没人相信她的故事，因为经查明船上所有人都在。随着船驶过荒凉的北海，她冒着生命危险固执地寻找答案。', '/static/posters/10号舱里的女人_medium.jpg', 3.5, 2, 1290879, 6.249, '2025-10-28 11:13:39', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (68, '郊狼', '科林·米尼汉', '贾斯汀·朗, 米拉·哈里斯, 布列塔尼·艾伦, 凯特·波茨沃斯, 诺伯特·里奥·布茨', '2025-10-02', '在好莱坞山脉，一场凶猛的野火肆虐，一家人不得不与一群凶恶的郊狼展开生死搏斗。烈火和野兽双重威胁之下，险象环生的求生之战一触即发。面对无情的火焰和凶残的野兽，他们能否在这场浩劫中幸存下来？', '/static/posters/郊狼_medium.jpg', 3.8, 6, 1386827, 5.375, '2025-10-28 11:13:39', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (69, 'F1：狂飙飞车', '约瑟夫·科辛斯基', '布拉德·皮特, 达姆森·伊卓瑞斯, 哈维尔·巴登, 凯瑞·康顿, 托比亚斯·门基斯', '2025-06-25', '桑尼·海耶斯曾经是F1赛场上最具潜力的天才新星，但一场意外葬送了他的职业生涯，从此他沦为人们口中最生不逢时的"沧海遗珠"。三十年后的如今，桑尼是一名自由职业的落魄赛车手，他的前队友——如今是濒临破产的F1车队老板鲁本·塞万提斯却突然找上门来。鲁本说服桑尼重返F1赛场，这不仅是拯救他车队的最后希望，更是桑尼向世界证明自己仍是顶尖车手的最佳契机。桑尼将与车队的热门新秀乔舒亚·皮尔斯并肩前行，这位年轻的车手也渴望在赛道上书写自己的传奇。', '/static/posters/F1：狂飙飞车_medium.jpg', 2.3, 3, 911430, 7.815, '2025-10-28 11:13:39', '2025-10-28 11:59:43');
INSERT INTO `main_film` VALUES (70, '一战再战', '保罗·托马斯·安德森', '莱昂纳多·迪卡普里奥, 西恩·潘, Chase Infiniti, 本尼西奥·德尔·托罗, 雷吉娜·赫尔', '2025-09-23', '落魄潦倒的革命者鲍勃（莱昂纳多·迪卡普里奥 饰）终日生活在草木皆兵的偏执状态，他与世隔绝，只和坚韧自立的女儿薇拉（蔡斯·英菲尼迪 饰）相依为命。然而，当鲍勃的宿敌（西恩·潘 饰）在16年后再度现身，女儿也突然失踪，这位曾经的激进分子仓促踏上了寻女之路，父女二人不得不直面他过往行为种下的恶果……', '/static/posters/一战再战_medium.jpg', 3, 2, 1054867, 7.744, '2025-10-28 11:13:40', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (71, '好狗狗', 'Ben Leonberg', 'Indy, Shane Jensen, 拉瑞·凡斯登, Arielle Friedman, 斯图尔特·鲁丁', '2025-10-01', '一部由狗狗担任主角的恐怖片。 小狗印第跟随他的主人和挚友托德踏上了一段新的旅途，离开城市生活，搬到了乡下一栋空置已久的旧宅。然而搬进家后，印第却立刻被充满空阔角落的不详气息所困扰。一只死去已久的狗的魂灵现身，向印第发出若有若无的警告，而前任房主惨死的景象更是突然浮现在它面前。当托德渐渐屈服于萦绕房子的黑暗力量，印第必须与来自死亡的恶灵搏斗，保护它挚爱的人类。', '/static/posters/好狗狗_medium.jpg', 3.7, 3, 1422096, 7.059, '2025-10-28 11:13:41', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (72, '哪吒之魔童闹海', '饺子', '吕艳婷, 囧森瑟夫, 瀚墨, 陈浩, 绿绮', '2025-01-29', '天劫之后，哪吒、敖丙的灵魂虽保住了，但肉身很快会魂飞魄散。太乙真人打算用七色宝莲给二人重塑肉身。但是在重塑肉身的过程中却遇到重重困难，哪吒、敖丙的命运将走向何方？ 申公豹放出被囚的四龙王，东海龙王敖光表示"我若出战，就让陈塘关鸡犬不留"，哪吒为了守卫陈塘关将与四海龙王大打出手。', '/static/posters/哪吒之魔童闹海_medium.jpg', 3.8, 4, 980477, 8.037, '2025-10-28 11:13:42', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (73, '伊甸', '朗·霍华德', '西德妮·斯维尼, 裘德·洛, 丹尼尔·布鲁赫, 凡妮莎•柯比, 安娜·德·阿玛斯', '2025-04-03', '一座资源紧缺的无人岛，三组各怀心思的求生者，毒害、背叛、爆头... 荒岛硬核大逃杀，残酷社达动物园！当粮食枯竭、水源污染、信任崩盘，生存成了唯一的目标。为了活下去，人性被兽性替代，欲望滋生出邪恶，而谁又将成功活到最后……', '/static/posters/伊甸_medium.jpg', 2.6, 5, 1042834, 6.8, '2025-10-28 11:13:42', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (74, '小人物2', 'Timo Tjahjanto', '鲍勃·奥登科克, 康妮·尼尔森, 约翰·奥提兹, 科林·汉克斯, 罗伯特·菲茨杰拉德·迪格斯', '2025-08-13', '昔日"小人物"哈奇携妻小赴偏远小镇度假，却被恶警与黑帮围剿。枪火惊梦，全家被迫联手反击。在枪火与尖叫交织的旋转木马上，哈奇终于明白：真正的"退休"不是金盆洗手，而是让家人活下来的那一刻。', '/static/posters/小人物2_medium.jpg', 5, 1, 1007734, 7.077, '2025-10-28 11:13:43', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (75, 'Frankenstein', '吉尔莫·德尔·托罗', '奥斯卡·伊萨克, 雅各布·艾洛蒂, 米娅·高斯, 克里斯托弗·瓦尔兹, 费利克斯·卡默雷尔', '2025-10-17', '', '/static/posters/Frankenstein_medium.jpg', 3.3, 3, 1062722, 8, '2025-10-28 11:13:43', '2025-10-28 12:05:39');
INSERT INTO `main_film` VALUES (76, '银莲花', 'Ronan Day-Lewis', '丹尼尔·戴-刘易斯, 肖恩·宾, 萨曼莎·莫顿, Samuel Bottomley, Safia Oakley-Green', '2025-10-02', '中年男子（肖恩·宾 饰）从郊区的家中启程，走进一片森林，去探望与世隔绝、形同陌路的隐居兄弟（丹尼尔·戴-刘易斯 饰）。两人因一段神秘而复杂的往事相连，关系充满张力，却偶尔流露温情。几十年前的某桩毁灭性事件，永远改变了他们的命运。', '/static/posters/银莲花_medium.jpg', 2.7, 3, 1364608, 5.8, '2025-10-28 11:13:43', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (77, '莱拉', 'Ram Narayan', 'Vishwak Sen, Akansha Sharma, Babloo Prithiveeraj, Abhimanyu Singh, Vineet Kumar', '2025-02-14', 'Sonu (Vishwak Sen) 是一家美容院的老板，受到附近许多女性的羡慕。然而，他发现自己与当地流氓 Rustum (Abhimanyu Singh) 和 SI Shankar (Babloo Prithviraj) 不和。为了逃避他们的威胁，Sonu 以 Laila 的身份接受了新身份。这一转变如何展开以及它会导致什么后果构成了故事的其余部分。', '/static/posters/莱拉_medium.jpg', 3, 2, 1403735, 5.2, '2025-10-28 11:13:44', '2025-10-28 12:05:36');
INSERT INTO `main_film` VALUES (78, '坏蛋联盟2', '皮埃尔·佩里费尔', '山姆·洛克威尔, 马克·马伦, 奥卡菲娜, 克雷格·罗宾逊, 安东尼·拉莫斯', '2025-07-24', '坏蛋联盟正在努力适应作为好人的新生活，寻求他人的信任和接受，它们被一个全女性阵容的犯罪团体强迫做最后一单生意，不得不脱离退休状态，再次出山重操旧业。', '/static/posters/坏蛋联盟2_medium.jpg', 3.3, 3, 1175942, 7.757, '2025-10-28 11:13:44', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (79, '可拉米洛', 'Diego Freitas', 'Rafael Vitti, Amendoim, Arianne Botelho, Kelzy Ecard, Bruno Vinicius', '2025-10-07', '在这部暖心的剧情片中，一名前途无量的厨师在得知重大诊断结果后，籍着一只毛茸茸的狗朋友的帮助找到了希望与欢乐。', '/static/posters/可拉米洛_medium.jpg', 3.7, 3, 1277988, 7.664, '2025-10-28 11:13:45', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (80, '金发姑娘与三只熊：死亡与粥', 'Craig Rees', 'Olga Solo, Abigail Huxley, Jimmy Roberts, Robson Medler, Julian Amos', '2024-06-05', '当一群人在年度团聚假期来到了错误的地址时，绝望之下，他们闯入了一所偏僻的房子，结果却发现这房子属于一群装扮成金发姑娘和三只熊的精神病杀手。', '/static/posters/金发姑娘与三只熊：死亡与粥_medium.jpg', 2.8, 5, 1186274, 4.091, '2025-10-28 11:13:45', '2025-10-28 12:05:36');
INSERT INTO `main_film` VALUES (81, 'Gabby\'s Dollhouse: The Movie', 'Ryan Crego', 'Laila Lockhart Kraner, Gloria Estefan, 克丽丝滕·威格, Logan Bailey, 爱德华多·佛朗哥', '2025-09-13', '', '/static/posters/Gabby\'s_Dollhouse__The_Movie_medium.jpg', 2.6, 5, 1280282, 6.9, '2025-10-28 11:13:45', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (82, '无可争议的姜戈', 'Claudio Del Falco', 'Claudio Del Falco, 托马斯·阿拉纳, Michael Segal, 奥塔维亚诺·戴尔·阿夸, Clara Guggiari', '2024-04-22', '在这片法外之地，不公与暴行肆虐横行。姜戈以血为誓，披荆斩棘，在枪火与刀锋的洗礼中，为扭曲的大地重铸正义的法则。', '/static/posters/无可争议的姜戈_medium.jpg', 3, 1, 1357886, 6.056, '2025-10-28 11:13:46', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (83, '星际宝贝史迪奇', '迪恩·弗莱舍·坎普', '玛雅·凯洛哈, 西德尼·阿古顿, 克里斯·桑德斯, 扎克·加利费安纳基斯, 比利·马格努森', '2025-05-17', '来自外星的"实验品626"史迪奇（克里斯·桑德斯 配音）在一场太空追捕中意外降落在夏威夷海岛，与小女孩莉萝（玛雅·凯洛哈 饰）相遇，为了躲避追捕，史迪奇伪装成小狗进入了莉萝的生活，发生了一段极其风趣又不失感人的故事。', '/static/posters/星际宝贝史迪奇_medium.jpg', 2.5, 6, 552524, 7.253, '2025-10-28 11:13:47', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (84, '原谅我神父', 'Fredi \'Kruga\' Nwaka', 'Simon Haines, Tim Faraday, Celine Arden, Tara Hoyos-Martinez, Fredi \'Kruga\' Nwaka', '2024-11-04', '当在一栋别墅里发现一些被肢解的尸体时,经验丰富的泰勒警探被指控寻找凶手。一个不太可能的嫌疑犯揭露了一些秘密被带到了坟墓,一些秘密把我们带到了坟墓。', '/static/posters/原谅我神父_medium.jpg', 2.5, 2, 1364992, 6.333, '2025-10-28 11:13:47', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (85, '我的过错：伦敦', 'Dani Girdwood, Charlotte Fassler', 'Asha Banks, Matthew Broome, 伊芙·麦克林, 雷·费隆, Enva Lewis', '2025-02-12', '18岁的诺亚从美国搬到了伦敦，因为她的母亲最近爱上了一位英国富商，威廉。诺亚见到了威廉的儿子，坏男孩尼克，并很快发现他们之间有种让彼此无法抗拒的吸引力。花了一整个夏天适应新生活的诺亚，将会在她第一次坠入爱河之际，猝不及防地迎来她那令人绝望的过去。', '/static/posters/我的过错：伦敦_medium.jpg', 3.2, 4, 1294203, 7.459, '2025-10-28 11:13:47', '2025-10-28 12:05:46');
INSERT INTO `main_film` VALUES (86, '寻梦环游记', '李·昂克里奇', '安东尼·冈萨雷斯, 盖尔·加西亚·伯纳尔, 本杰明·布拉特, 阿莱娜·尤波, 芮妮·维克多', '2017-10-27', '一个鞋匠家庭出身的12岁墨西哥小男孩米格，自幼有一个音乐梦，但音乐却是被家庭所禁止的，他们认为自己被音乐诅咒了。在米格秘密追寻音乐梦时，因为触碰了一把吉他而踏上了亡灵土地。每年的亡灵节日，逝去的家人都会返回人间与亲人团聚，但从来还没有人去到过亡灵的世界。米格被多彩绚丽的亡灵世界所震撼，而更令他的惊喜的是，他重逢了逝去的太爷爷和祖辈们，一家人要想办法将米格重新送回人间……', '/static/posters/寻梦环游记_medium.jpg', 3, 3, 354912, 8.2, '2025-10-28 11:13:48', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (87, 'Diamanti', 'Ferzan Özpetek', '路易莎·拉涅瑞, 杰丝敏·特丽卡, Elena Sofia Ricci, Lunetta Savino, 瓦内萨·斯格勒雷', '2024-12-19', '', '/static/posters/Diamanti_medium.jpg', 3, 5, 1299046, 7.21, '2025-10-28 11:13:48', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (88, '复仇者联盟', '乔斯·韦登', '小罗伯特·唐尼, 克里斯·埃文斯, 马克·鲁法洛, 克里斯·海姆斯沃斯, 斯嘉丽·约翰逊', '2012-04-25', '一股突如其来的强大邪恶势力对地球造成致命威胁，没有任何一个超级英雄能够单独抵挡。长期致力于保护全球安危的神盾局感到措手不及，其指挥官尼克·弗瑞意识到他必须创建一个"史上最强"的联盟组织， 云集各方超级英雄一起发威，才能拯救世界于水深火热，抵御黑暗势力的侵袭。于是由六大超级英雄——"钢铁侠"、"雷神" 、"美国队长"、"绿巨人" 、"黑寡妇"和"鹰眼"组成的 "复仇者联盟"应运而生。他们各显神通，团结一心，终于战胜了邪恶势力，保证了地球的安全。', '/static/posters/复仇者联盟_medium.jpg', 2, 1, 24428, 7.836, '2025-10-28 11:13:49', '2025-10-28 12:05:35');
INSERT INTO `main_film` VALUES (89, '改日再战', 'James Mark', '吉姆·貝魯什, 马丁·科夫, 埃里克·约翰逊, Ennis Esmer, Chuck Liddell', '2024-10-09', '', '/static/posters/改日再战_medium.jpg', 3.5, 2, 1053008, 5.111, '2025-10-28 11:13:49', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (90, '疾速追杀：芭蕾杀姬', '伦·怀斯曼', '安娜·德·阿玛斯, 基努·里维斯, 伊恩·麦柯肖恩, 安杰丽卡·休斯顿, 加布里埃尔·伯恩', '2025-06-04', '父亲惨遭杀害，少女伊芙（安娜·德·阿玛斯 饰）被迫加入杀手组织，在这里她被培养成为一名芭蕾舞者，同时接受了长达12年的魔鬼训练成为了顶级杀手，开启了血刃仇人的杀戮之旅。她不仅要独自一人完成组织下达的死亡任务，还要暗中搜集杀父仇家的信息。随时丧命的极端危险、各方势力的联合围剿，让伊芙的复仇之路艰难无比。同时，她又被传说中的杀手约翰·威克（基努·里维斯 饰）锁定，新老杀神狭路相逢，伊芙必须在被约翰追到之前杀出血路完成复仇。危险的倒计时开始，一场致命厮杀即将拉开血色序幕……', '/static/posters/疾速追杀：芭蕾杀姬_medium.jpg', 3, 4, 541671, 7.3, '2025-10-28 11:13:51', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (91, '致命录像带：万圣节', 'Bryan M. Ferguson, Casper Kelly, Micheline Pitt-Norman', 'Lawson Greyson, Sarah Nicklin, Jenna Hogan, Isabella Feliciana, Sean Berube', '2025-09-19', '一盒以万圣节为主题的录像带引发了一系列扭曲而血腥的故事，将"不给糖就捣蛋"的节日变成了一场生存之战。', '/static/posters/致命录像带：万圣节_medium.jpg', 4, 3, 1373445, 6.302, '2025-10-28 11:13:51', '2025-10-28 11:59:43');
INSERT INTO `main_film` VALUES (92, '恶毒', 'Bryan Bertino', '达科塔·范宁, 凯瑟琳·亨特, 玛丽·麦科马克, 雷切尔·布兰查德, 迪文·妮科塔', '2025-09-19', '影片围绕着一个女人展开，当她意外地收到一个神秘的木箱时，她的日常生活发生了险恶的转折。她没有意识到它所蕴含的黑暗力量，很快发现了盒子和即将到来的生命威胁之间的不祥联系。随着盒子向她发出令人不寒而栗的最后通牒——要么采购三件特定物品，要么屈服于致命的命运，展开的 叙述愈演愈烈。随着每一个转折，女人都踏上了一段悬疑的旅程，与时间赛跑，揭开邪恶力量背后的秘密，并在危险的生存之路上航行。', '/static/posters/恶毒_medium.jpg', 3, 3, 1251717, 6.114, '2025-10-28 11:13:51', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (93, 'Ligaw', 'Omar Deroca', '罗伯·吉恩托, Ali Asistio, JC Tan, 拉什·弗洛雷斯, Jodi Garcia', '2025-05-09', '', '/static/posters/Ligaw_medium.jpg', 2.7, 3, 1470086, 6, '2025-10-28 11:13:52', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (94, '死神来了：血脉诅咒', '亚当 B·斯坦因, 扎克·利波夫斯基', '凯特琳·桑塔·胡安娜, 特欧·布里奥尼斯, 莱亚·吉斯特德, 理查德·哈蒙, 欧文·帕特里克·乔伊纳', '2025-05-14', '大学生斯蒂芬妮（凯特琳·桑塔·胡安娜 Kaitlyn Santa Juana 饰）长期被噩梦困扰，她决定返回家乡寻找噩梦起源，却意外发现曾发生在外婆艾莉丝身上的离奇旧事，并牵连出流淌在整个家族血脉中的秘密：死神诅咒。当她试图破解诅咒密码，却发现死神的镰刀早已垂下…… 随着身边亲人一个个离奇惨死，斯蒂芬妮还能带领幸存者逃脱死神的宿命猎杀吗？', '/static/posters/死神来了：血脉诅咒_medium.jpg', 2.7, 3, 574475, 7.098, '2025-10-28 11:13:52', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (95, '白头神探：智斗灭世狂人', 'Akiva Schaffer', '连姆·尼森, 帕米拉·安德森, 保罗·沃尔特·豪瑟, 丹尼·休斯顿, 希·庞德', '2025-07-30', '白头神探的儿子小弗兰克（连姆·尼森 Liam Neeson 饰）即将上演最无厘头的一次"营救"行动。', '/static/posters/白头神探：智斗灭世狂人_medium.jpg', 3.7, 3, 1035259, 6.569, '2025-10-28 11:13:53', '2025-10-28 12:05:35');
INSERT INTO `main_film` VALUES (96, '冬日之死', '布莱恩·寇克', '艾玛·汤普森, 朱迪·格雷尔, 马克·门查卡, 劳雷尔·马斯登, 盖亚·怀斯', '2025-09-23', '一名孤身穿越明尼苏达北境雪原的女子，意外撞破少女绑架现场。百里荒原杳无人烟，暴雪割断通讯网络，她成为深陷绝境的少女唯一生机。', '/static/posters/冬日之死_medium.jpg', 3.8, 6, 1235746, 6.5, '2025-10-28 11:13:53', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (97, '丑陋的继姐', 'Emilie Blichfeldt', 'Lea Mathilde Skar-Myren, 安妮·达尔·托普, 西娅·索菲·内丝, Flo Fagerli, Isac Calmroth', '2025-03-07', '在一个童话王国里，美丽是一件残酷的事情，埃尔维拉与她美丽得令人难以置信的继姐姐竞争，她将不惜一切代价吸引王子的目光。', '/static/posters/丑陋的继姐_medium.jpg', 2.8, 4, 1284120, 7.3, '2025-10-28 11:13:53', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (98, '冰路营救2：复仇', '乔纳森·汉斯雷', '连姆·尼森, 范冰冰, 马库斯·托马斯, Grace O\'Sullivan, Saksham Sharma', '2025-06-27', '前作主角迈克前往尼泊尔，将弟弟的骨灰洒在珠穆朗玛峰上。当迈克和他的登山向导在乘坐旅游巴士旅行时遇到一群雇佣兵时，他们被迫战斗以营救自己、乘客和国家。', '/static/posters/冰路营救2：复仇_medium.jpg', 3.5, 2, 1119878, 6.319, '2025-10-28 11:13:54', '2025-10-28 11:59:43');
INSERT INTO `main_film` VALUES (99, '僵尸新娘', '蒂姆·伯顿, 迈克·约翰逊', '约翰尼·德普, 海伦娜·伯翰·卡特, 艾米丽·沃森, 特蕾西·乌尔曼, 保罗·怀特豪斯', '2005-09-12', '维克多的父母为儿子安排了一场婚姻，未婚妻是没落贵族小姐维多利亚。维克多内向敏感，不善表达，于是婚礼前夜来到小树林中暗暗排练宣誓仪式。然而，意外发生了。当他把戒指套进地上一根树枝上面时，愕然发现树枝竟然变成了一根腐烂了的手指！维克多惊魂未定，地动山摇间眼前竟然出现了一个僵尸新娘。而这个腐烂的手指，正是长在她的身上。僵尸新娘情真意切的说自己就是维克多的合法妻子。维克多惊异万分，慢慢得知原来这个女子死于一个新婚之夜，她一直在这里等她丈夫的到来。在小树林里维克多不但认识了这个女子，还看到这片死人世界一片欢乐和睦的气氛，他被眼前的情景深深感染，畏惧渐渐散去。然而，在两个世界，两个新娘之间，维克多该如何抉择。', '/static/posters/僵尸新娘_medium.jpg', 3.3, 3, 3933, 7.583, '2025-10-28 11:13:54', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (100, '蛮荒镇', 'Marcel Walz', 'Adriane McLean, Sarah French, Gigi Gustin, Dazelle Yvette, Adam Bucci', '2024-03-13', '1976年，一个摄影小组来到一处荒地拍摄，不料他们走进了这辈子最后的工作地点', '/static/posters/蛮荒镇_medium.jpg', 3.5, 4, 1221415, 4.4, '2025-10-28 11:13:54', '2025-10-28 12:05:39');
INSERT INTO `main_film` VALUES (101, 'E poi si vede', 'Giovanni Calvaruso', 'Fabrizio Sansone, Federico Sansone, Donatella Finocchiaro, Paola Minaccioni, Ester Pantano', '2025-03-27', '', '/static/posters/E_poi_si_vede_medium.jpg', 4, 2, 1256208, 6, '2025-10-28 11:13:55', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (102, '哪吒之魔童降世', '饺子', '吕艳婷, 囧森瑟夫, 瀚墨, 陈浩, 绿绮', '2019-07-26', '天地灵气孕育出一颗能量巨大的混元珠，元始天尊将混元珠提炼成灵珠和魔丸，灵珠投胎为人，助周伐纣时可堪大用；而魔丸则会诞出魔王，为祸人间。元始天尊启动了天劫咒语，3年后天雷将会降临，摧毁魔丸。太乙受命将灵珠托生于陈塘关李靖家的儿子哪吒身上。然而阴差阳错，灵珠和魔丸竟然被掉包。本应是灵珠英雄的哪吒却成了混世大魔王。调皮捣蛋顽劣不堪的哪吒却徒有一颗做英雄的心。然而面对众人对魔丸的误解和即将来临的天雷的降临，哪吒是否命中注定会立地成魔？他将何去何从？', '/static/posters/哪吒之魔童降世_medium.jpg', 1, 1, 615453, 7.891, '2025-10-28 11:13:55', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (103, 'LEGO Frozen: Operation Puffins', 'Alexandru Nagy', 'Abby Trott, 丹妮尔·比苏蒂, 艾伦·图代克, 斯蒂芬 J·安德森, Jake Green', '2025-10-23', '', '/static/posters/LEGO_Frozen__Operation_Puffins_medium.jpg', 2, 1, 1549292, 8, '2025-10-28 11:13:55', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (104, '小鹿斑比：清算', 'Dan Allen', '罗克珊·麦基, Tom Mulheron, Adrian Relph, Nicola Wright, Alex Cooke', '2025-07-11', '该片将继续"毁童年"，改编自同名迪士尼动画的原作——澳大利亚童书《小鹿斑比》，由《恶魔整容》编剧Scott Jeffrey执导，Rhys Frake-Waterfield等制作。导演Jeffrey透露："该片将会把我们所熟知和喜爱的1928年故事做一个极其暗黑的新编，设计灵感来自网飞的《黑森灵》，斑比会是隐藏在荒野中的残暴的杀戮机器，准备好迎接发狂的斑比吧！"', '/static/posters/小鹿斑比：清算_medium.jpg', 2.3, 3, 1049942, 6, '2025-10-28 11:13:56', '2025-10-28 11:59:43');
INSERT INTO `main_film` VALUES (105, '死神之夜', 'Brandon Christensen', '杰西卡·克莱门特, 瑞安·罗宾斯, 莎莫·H·豪威尔, 基冈·康纳·特雷西, 马蒂·菲诺奇奥', '2025-10-16', '在20世纪80年代的郊区，一名年轻女子被保姆杀手"死神"残忍杀害整整一年后，她的姐姐迪娜回到家中，恰逢"死神"再度现身。当迪娜受托照看镇警长儿子的那个夜晚，事态逐渐升级，最终引发了令人震惊且意想不到的结局。', '/static/posters/死神之夜_medium.jpg', 3, 1, 1502943, 7, '2025-10-28 11:13:56', '2025-10-28 11:59:34');
INSERT INTO `main_film` VALUES (106, '某种物质', '科拉莉·法尔雅', '黛米·摩尔, 玛格丽特·库里, 丹尼斯·奎德, 爱德华·汉密尔顿-克拉克, 戈雷·阿布拉姆斯', '2024-09-07', '曾经红极一时的好莱坞巨星伊丽莎白无法面对自己老去的容颜，决定使用一种名为"完美物质"的黑市药物，透过注射药物的细胞复制物质，创造出更年轻、更好的另一个自己。"年华老去"及"年轻貌美"的自己该如何共存？会是更强烈的容貌焦虑大战？还是要不断迎合大众对"美"的期待？一场自我身体主导权的争夺战即将上演……', '/static/posters/某种物质_medium.jpg', 4, 1, 933260, 7.147, '2025-10-28 11:13:57', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (107, '地球特派员', '玛德琳·莎拉芬, 石之予, 阿德里安·莫利纳', '约纳斯·基布雷亚布, Remy Edgerly, 佐伊·索尔达娜, 布拉德·加勒特, Brandon Moon', '2025-06-18', '埃利奥是一个想象力丰富、痴迷外星人、对太空狂热的孩子，当他被传送到星际组织 "共融宇宙"时，他将经历一场史诗般的冒险。埃利奥被误认为是地球的领袖，他必须与古怪的外星生命体建立新的联系，渡过一场星际危机，并以某种方式发现自己真正的身份和位置。', '/static/posters/地球特派员_medium.jpg', 2.8, 6, 1022787, 6.967, '2025-10-28 11:13:57', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (108, '梅根2.0', '热拉尔·约翰斯通', '艾莉森·威廉姆斯, 维奥莱特·麦格劳, 艾米·唐娜, 珍娜·戴维斯, 布莱恩·乔丹·阿尔瓦雷斯', '2025-06-25', '第二部仍以女孩凯蒂和她的姨妈珍玛为主线，她们遭到了下一代机器人"艾米莉亚"的疯狂攻击，而本已沦为智能语音助手的梅根，似乎是帮助她们对抗艾米莉亚的绝佳选择。', '/static/posters/梅根2.0_medium.jpg', 3, 1, 1071585, 7.4, '2025-10-28 11:13:57', '2025-10-28 11:59:41');
INSERT INTO `main_film` VALUES (109, '海洋奇缘2', '小戴夫·德里克, 杰森·汉德, 达娜·莱杜克斯·米勒', '奥丽伊·卡瓦洛, 道恩·强森, 华拉莱·钟, 罗丝·马塔费奥, David Fane', '2024-11-21', '在祖灵突如其来的呼唤之下，莫阿娜（奥丽伊·卡瓦洛 Auli\'i Cravalho 配音）、毛伊（道恩·强森 Dwayne Johnson 配音）和新船员们将启程航向大洋洲的彼端，一路深入危险未知的海域，面对一场前所未见的新冒险。', '/static/posters/海洋奇缘2_medium.jpg', 2, 3, 1241982, 7.03, '2025-10-28 11:13:58', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (110, 'Assassin', '', '吕良伟, Ming Wang', '2025-09-26', '', NULL, 4, 3, 1552819, 4.375, '2025-10-28 11:14:00', '2025-10-28 11:59:41');
INSERT INTO `main_film` VALUES (111, '告诉我你想要什么', 'Lucía Alemany', '加布里埃拉·安德拉达, Mario Ermito, 西莉亚·费杰罗, 大卫·索兰斯, Alba Ribas', '2024-11-29', '父亲去世后，埃里克·齐默尔曼前往西班牙监督公司的分支机构。在马德里，他爱上了朱迪思，并开始了一段充满探索的激烈的性爱关系。埃里克担心他的秘密可能会结束他们的恋情。改编自梅根·麦克斯韦尔（Megan Maxwell）的畅销小说《告诉我你想要什么（Tell Me What You Want）》。', '/static/posters/告诉我你想要什么_medium.jpg', 2, 2, 1252309, 6.198, '2025-10-28 11:14:00', '2025-10-28 11:59:38');
INSERT INTO `main_film` VALUES (112, '凶降喜讯', '卞成贤', '薛景求, 红炅, 柳升范, 山田孝之, 椎名桔平', '2025-09-05', '一架民用客机在飞行途中突然遭到劫持，地面上的救援团队立即展开行动，试图拯救机上的人质。与此同时，一个神秘的天才人物提出了一项疯狂的计划，企图让被劫持的飞机改道降落在首尔。在这场与时间赛跑的救援行动中，各方势力斗智斗勇，冲突不断升级。而一项秘密行动也在暗中悄然展开，为整个事件增添了更多未知的变数。', '/static/posters/凶降喜讯_medium.jpg', 3, 4, 1296404, 7.058, '2025-10-28 11:14:00', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (113, '移动迷宫', '韦斯·波尔', '迪伦·奥布莱恩, 卡雅·斯考达里奥, 阿梅尔·艾米恩, 托马斯·布罗迪-桑斯特, 李起弘', '2014-09-10', '男孩托马斯（迪伦·欧布莱恩 Dylan O\'Brien 饰）在电梯中醒来，奇怪的是他除了名字之外什么都记不得。当电梯打开，他来到了一个陌生的地方"林间空地"。这里四周被高大的石头墙包围着，墙内住着许多男孩，有纽特（托马斯·桑斯特 Thomas Sangster 饰）、查克（布雷克·库珀 Blake Cooper 饰）、米诺（李基弘 Ki Hong Lee 饰）等人，他们都被困在迷宫里，而墙外还有一群巨大的怪兽威胁着。一天，电梯为他们送来了一个女孩特雷莎（卡雅·斯考达里奥 Kaya Scodelario 饰），她是来这里的第一个女孩。此后，迷宫逐渐开始发生变化，一切都陷入了混乱中，托马斯和特雷莎决定一起走上破解迷宫之路，找出迷宫背后令人不寒而栗的秘密。影片改编自詹姆斯·达什纳撰写的同名反乌托邦科幻小说三部曲的第一本。', '/static/posters/移动迷宫_medium.jpg', 7.192, 17647, 198663, 7.192, '2025-10-28 11:14:01', '2025-10-28 11:17:52');
INSERT INTO `main_film` VALUES (114, '峡谷', '斯科特·德里克森', '迈尔斯·特勒, 安雅·泰勒-乔伊, 西格妮·韦弗, 索佩·迪瑞苏, 威廉·休斯顿', '2025-02-13', '两名训练有素的特工被派去看守一个神秘峡谷，期间相隔两侧的两人反而越走越近。峡谷中的邪恶力量浮现后，他们必须携手合作，才能与之抗衡，生存下去。', '/static/posters/峡谷_medium.jpg', 3.5, 4, 950396, 7.7, '2025-10-28 11:14:01', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (115, '火烧天堂镇', '保罗·格林格拉斯', '马修·麦康纳, 亚美莉卡·费雷拉, 尤尔·瓦斯克斯, Ashlie Atkinson, Kimberli Flores', '2025-09-19', '改编自真实事件，讲述一名意志坚定的司机父亲在猛烈的野火中拼死救援一位尽责的老师与她的学生们。', '/static/posters/火烧天堂镇_medium.jpg', 2.3, 7, 1236470, 7.211, '2025-10-28 11:14:02', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (116, '鬼妈妈', '亨利·塞利克', '达科塔·范宁, 泰瑞·海切尔, 詹妮弗·桑德斯, 唐·弗兰奇, 基思·大卫', '2009-02-05', '本片根据畅销小说改编而成。卡洛琳是一个充满好奇心的女孩，她在新家里发现了一扇神秘的门，通过那扇门，她进入了一个与现实平行的世界。表面看来，这个世界只是现实世界的镜像复制，其中的事物与现实里的几乎一模一样，但却充满了奇幻。在这里卡洛琳碰见了很多奇怪的人，包括她的"赝品母亲"，后者想将其永远留在这里。而卡洛琳必须依靠自己的机智、决心和勇气，才能重回现实，拯救自己的家庭。', '/static/posters/鬼妈妈_medium.jpg', 4, 1, 14836, 7.897, '2025-10-28 11:14:02', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (117, '圣诞夜惊魂', '亨利·塞利克', '丹尼·艾夫曼, 克里斯·萨兰登, 凯瑟琳·欧哈拉, 威廉·赫基, 格伦·沙迪克斯', '1993-10-09', '万圣镇的各位鬼怪，已经习惯于在每年万圣节那天出没搞作一下，他们是彻头彻尾的少根筋的生物，只晓得如何吓人。而南瓜王子杰克，是非常与众不同的一个。他已经厌倦了带给人们惊恐的玩意，一心想做出某些改变。偶然一次打开了圣诞镇的大门，让他眼前豁然一亮，杰克心中燃起了要带领兄弟制造圣诞欢乐的决心。但是，这帮万圣镇的鬼怪们似乎并不明白其中深意。杰克绑架了胖乎乎的圣诞老人，吩咐伙计们开始埋头制作圣诞礼物。满脑只有恐怖点子的万圣镇兄弟，又怎能逃过思维惯性，做出令人欢乐的礼物呢。于是，恐怖的、吓人的礼物将在圣诞那夜抛给孩子们，当杰克坐着人造鹿车派出礼物时，一枚高射炮正对准了这个好心办坏事的可怜虫。', '/static/posters/圣诞夜惊魂_medium.jpg', 5, 1, 9479, 7.835, '2025-10-28 11:14:02', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (118, '我的世界大电影', '杰瑞德·赫斯', '杰森·莫玛, 杰克·布莱克, 塞巴斯蒂安·尤金·汉森, 艾玛·迈尔斯, 达尼埃尔·布鲁克斯', '2025-03-31', '影片讲述四个"异类"——盖瑞特·"拾荒人"·加里森（杰森·莫玛 饰）、亨利（塞巴斯蒂安·尤金·汉森 饰）、娜塔莉（艾玛·迈尔斯 饰）和道恩（丹妮尔·布鲁克斯 饰）——正为生活中的琐事苦恼时，突然被拉入一个神秘的传送门，进入了"主世界"：一个依赖想象力的奇异方块乐园。为了回到现实世界，他们不仅要掌握这个世界的规则，还要在不速之客——资深工匠史蒂夫（杰克·布莱克 饰）的帮助下，迈上一场魔幻探险之旅。探险之旅充满挑战，五人必须要勇敢面对，发掘各自独特的创造力。创造力，正是他们重返现实世界的关键技能。', '/static/posters/我的世界大电影_medium.jpg', 3, 2, 950387, 6.357, '2025-10-28 11:14:03', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (119, '惊天大营救', '成思毅', '托尼·贾, 洪浚嘉, 释行宇, 姜皓文, 陈朵怡', '2024-12-05', '亡命之徒白安挟持富家小女孩贺婷，意图借此向其父复仇，却不料此举意外使贺婷逃过毒贩的灭门之灾。尽管年幼，贺婷却心智成熟，面对父亲生死未卜、自身孤苦无依的困境，她竟意外的向要杀自己父亲的仇敌白安提出合作。于是，两人携手并进，相互扶持，踏上了寻父之路。在这场充满未知与艰险的旅程中，他们既要应对外界的追捕与威胁，又要面对内心的挣扎与冲突，共同编织着一段非同寻常的营救传奇。', '/static/posters/惊天大营救_medium.jpg', 1, 2, 1382406, 7.553, '2025-10-28 11:14:03', '2025-10-28 12:05:39');
INSERT INTO `main_film` VALUES (120, '制暴：无限杀机', '大卫·阿耶', '杰森·斯坦森, 杰森·弗莱明, 梅拉布·尼尼泽, 马克西米利安·奥辛斯基, 柯基·法尔考', '2025-03-26', '影片改编自查克·迪克逊所著同名系列小说，主人公莱文·凯德（杰森·斯坦森 Jason Statham 饰）是黑色行动界的传奇人物，他放弃职业从事建筑工作，想过简单的生活，做女儿的好父亲，而当他老板的十几岁女儿珍妮突然消失后，莱文被召回要求重操旧业。在追踪过程中，莱文卷入到 一个邪恶的犯罪阴谋的中心，产生了连锁反应，将威胁到他的新生活方式。', '/static/posters/制暴：无限杀机_medium.jpg', 5, 2, 1197306, 6.702, '2025-10-28 11:14:03', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (121, '哈利·波特与魔法石', '克里斯·哥伦布', '丹尼尔·雷德克里夫, 鲁伯特·格林特, 艾玛·沃森, 理查德·哈里斯, 汤姆·费尔顿', '2001-11-16', '哈利·波特是一个孤儿，从小寄养在姨妈家，受尽欺凌。但就在哈利11岁生日的时候，他意外收到了霍格沃茨学院的入学通知书。哈利从该学院派来接他的巨人海格口中得知，这是一间魔法学院，并得知了自己的身世，原来哈利的父母都是伟大的魔法师，在对付伏地魔的战斗中双双献身，唯有哈利幸免于难。哈利进入霍格沃茨后，表现出了超乎想象的飞行天赋，得到麦格教授的推荐进入了格兰芬多的魁地奇球队。另一方面，哈利发现霍格沃茨学院内有一股黑暗势力似乎在暗暗滋长，揭开谜团的关键就在有凶恶的三头犬守护的房间内。哈利、罗恩和赫敏三个好朋友决定探个究竟。', '/static/posters/哈利·波特与魔法石_medium.jpg', 3.5, 2, 671, 7.9, '2025-10-28 11:14:04', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (122, '魔法蓝精灵', '克里斯·米勒', '蕾哈娜, 詹姆斯·科登, 尼克·奥弗曼, JP Karliak, 丹·李维', '2025-07-05', '蓝精灵村庄每日载歌载舞一片欢乐，直到蓝爸爸（约翰·古德曼 John Goodman 配音）被格格巫绑架打破了平静，蓝妹妹（蕾哈娜 Rihanna 配音）带领蓝精灵勇闯现实世界，用魔法和智慧开启冒险。', '/static/posters/魔法蓝精灵_medium.jpg', 2.5, 2, 936108, 5.936, '2025-10-28 11:14:04', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (123, 'Parking', 'Agustín Rolandelli', 'Horacio Camandulle, Marc Clotet, China Suárez, Rafael Spregelburd', '2025-10-17', '', '/static/posters/Parking_medium.jpg', 2.5, 2, 1565344, 8, '2025-10-28 11:14:05', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (124, '阿凡达：水之道', '詹姆斯·卡梅隆', '萨姆·沃辛顿, 佐伊·索尔达娜, 西格妮·韦弗, 史蒂芬·朗, 凯特·温斯莱特', '2022-12-14', '十多年过去了，曾经截瘫的前海军士兵杰克·萨利（萨姆·沃辛顿饰）永久变身为拥有地球人基因和纳威人基因的"阿凡达"，并与奥马蒂卡亚部落的族长之女奈蒂莉（佐伊·索尔达娜饰）结为夫妇。杰克已经完全适应了他的新身体和族长的身份，并和奈蒂莉有了三个孩子，还收养了格蕾丝留下的女儿琪莉（西格妮·韦弗 饰）。四个孩子里，老大纳特亚姆（杰米·福雷特斯 饰）最为懂事听话，也很会照顾弟弟妹妹；老二琪莉（西格妮·韦弗 饰）因为不知道自己的父亲是谁，有些敏感；老三洛克（布里坦·道尔顿 饰）酷爱冒险，是家里的闯祸精；最小的妹妹图克（特里尼蒂·布利斯 饰）总是黏着哥哥姐姐们。四人跟人类留下的孤儿"蜘蛛"（杰克·尚皮永饰）是形影不离的好朋友。原本，将地球人赶走后，杰克一家与族人过上了田园牧歌般的生活。然而，原本死去的迈尔斯·夸里奇上校（史蒂芬·朗饰）化身阿凡达重新归来，一心要找杰克和奈蒂莉复仇。为了族人的安危，也为了保护孩子，杰克决定带着家人离开，前往不易被找到的由罗娜尔（凯特·温斯莱特饰）和特诺瓦里（克利夫·柯蒂斯饰）领导的海洋部落，展开全新的生活。正当一家人经过重重磨合，终于适应以水构筑的新家园时，新的危机也在慢慢靠', '/static/posters/阿凡达：水之道_medium.jpg', 4.4, 5, 76600, 7.6, '2025-10-28 11:14:05', '2025-10-28 11:59:43');
INSERT INTO `main_film` VALUES (125, '蝙蝠侠：黑暗骑士', '克里斯托弗·诺兰', '克里斯蒂安·贝尔, 希斯·莱杰, 艾伦·艾克哈特, 迈克尔·凯恩, 玛吉·吉伦哈尔', '2008-07-16', '从亲眼目睹父母被杀的阴影中走出来的蝙蝠侠布鲁斯·韦恩（克里斯蒂安·贝尔 Christian Bale 饰），在戈登警长（加里·奥德曼 Gary Oldman 饰）和检察官哈维（艾伦·艾克哈特 Aaron Eckhart 饰）的帮助下，无后顾之忧地满世界奔波，与罪犯们做着永无休止的争斗，哥谭市的犯罪率也以惊人的速度持续下降。但在哥谭这个科技与污秽并存的城市，平静不可能维持得太久，很快新一轮的混乱就席卷了整个城市，人们再度被恐慌笼罩，而这一切混乱的源头正是小丑（希斯·莱杰 Heath Ledger 饰）。', '/static/posters/蝙蝠侠：黑暗骑士_medium.jpg', 8.524, 34600, 155, 8.524, '2025-10-28 11:14:05', '2025-10-28 11:17:40');
INSERT INTO `main_film` VALUES (126, '死侍与金刚狼', '肖恩·利维', '瑞安·雷诺兹, 休·杰克曼, 艾玛·科林, 马修·麦克费登, 达芙妮·基恩', '2024-07-24', '史上最另类超级英雄、语不惊人死不休的死侍睽违六年终于重返大银幕，首次加入漫威电影宇宙！除了与一众昔日战友重新聚首，更与睽别15年的金刚狼二度并肩作战、再续兄弟情谊。直面时间变异管理局的追捕，迎战让人意想不到的神秘劲敌卡桑德拉·诺瓦。即便如此，死侍也毫不畏惧，自信满满地宣称自己就是"漫威救世主"，并将改写漫威电影宇宙！', '/static/posters/死侍与金刚狼_medium.jpg', 4, 6, 533535, 7.571, '2025-10-28 11:14:06', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (127, '头脑特工队2', '凯尔西·曼恩', '艾米·波勒, 玛雅·霍克, 肯辛顿·塔尔曼, 丽莎·拉皮拉, 托尼·海尔', '2024-06-11', '小女孩莱莉刚步入青春期，在她的大脑总部，正经历着一场突如其来的大拆迁，为意想不到的新情绪腾出空间。一直以来配合默契的情绪小伙伴乐乐、忧忧、怒怒、怕怕和厌厌，在新情绪焦焦的突然到来时变得不知所措，并且她看起来不是孤身一人。', '/static/posters/头脑特工队2_medium.jpg', 4, 2, 1022789, 7.5, '2025-10-28 11:14:07', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (128, '复仇者联盟3：无限战争', '安东尼·罗素, 乔·罗素', '小罗伯特·唐尼, 克里斯·埃文斯, 克里斯·海姆斯沃斯, 乔什·布洛林, 马克·鲁法洛', '2018-04-25', '随着复仇者联盟及其盟友继续保护世界免受来自任何单一英雄难以承担的威胁，一个新的危险从宇宙的阴影中浮现——灭霸。作为一个星际恶名昭彰的暴君，他的目标是收集所有六颗无限宝石，这些宝石拥有难以想象的力量，并利用它们将扭曲的意志强加于现实的每一个角落。复仇者们为此奋斗的一切都指向了这一刻——地球和整个存在的命运从未如此不确定。', '/static/posters/复仇者联盟3：无限战争_medium.jpg', 8.235, 31080, 299536, 8.235, '2025-10-28 11:14:08', '2025-10-28 11:17:33');
INSERT INTO `main_film` VALUES (129, '王者', 'Justin Tipping', 'Tyriq Withers, 马龙·韦恩斯, 朱莉娅·福克斯, 蒂姆·海德克, Jim Jefferies', '2025-09-18', '"为了达到伟大，你愿意牺牲什么？"一个新人职业球员的梦想和潜力，因为接受一个荣誉满身的老将的指导，而变成一场可怕、荒唐的噩梦。', '/static/posters/王者_medium.jpg', 1.3, 3, 986097, 5.881, '2025-10-28 11:14:09', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (130, '拯救地球', '约戈斯·兰西莫斯', '艾玛·斯通, 杰西·普莱蒙, Aidan Delbis, Stavros Halkias, 艾丽西亚·西尔弗斯通', '2025-10-23', '两名痴迷阴谋论的年轻男子绑架了某大公司位高权重的首席执行官，他们坚信对方是一名蓄意毁灭地球的外星人。', '/static/posters/拯救地球_medium.jpg', 2.5, 4, 701387, 7.8, '2025-10-28 11:14:10', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (131, '教父', '弗朗西斯·科波拉', '马龙·白兰度, 阿尔·帕西诺, 詹姆斯·凯恩, 罗伯特·杜瓦尔, 理查德·萨尔瓦托雷·卡斯特拉诺', '1972-03-14', '40年代的美国，"教父"维托·唐·柯里昂是黑手党柯里昂家族的首领，带领家族从事非法的勾当，但同时他也是许多弱小平民的保护神，深得人们爱戴。因为拒绝了毒枭索洛索的毒品交易要求，柯里昂家族和纽约其他几个黑手党家族的矛盾激化、圣诞前夕，索洛索劫持了"教父"的参谋汤姆，并派人暗杀"教父"；因为内奸的出卖，"教父"的大儿子逊尼被仇家杀害；小儿子麦克也被卷了进来，失去爱妻。黑手党家族之间的矛盾越来越白热化。年老的"教父"面对丧子之痛怎样统领全局？黑手党之间的仇杀如何落幕？谁是家族的内奸？谁又能够成为新一代的"教父"？血雨腥风和温情脉脉，在这部里程碑式的黑帮史诗巨片里真实上演。', '/static/posters/教父_medium.jpg', 2.5, 2, 238, 8.685, '2025-10-28 11:14:10', '2025-10-28 11:59:40');
INSERT INTO `main_film` VALUES (132, '德古拉', '吕克·贝松', '卡莱伯·兰德里·琼斯, 克里斯托弗·瓦尔兹, Zoë Bleu Sidel, Guillaume de Tonquédec, 玛蒂尔达·德·安杰利斯', '2025-07-30', '故事讲述 15 世纪的弗拉基米尔王子，在爱妻离世后诅咒上帝，最终化作吸血鬼；此后在 19 世纪的伦敦，他遇见了与妻子容貌一模一样的分身，却因执意追寻她而自取毁灭。', '/static/posters/德古拉_medium.jpg', 3.3, 3, 1246049, 7.171, '2025-10-28 11:14:11', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (133, '雷霆特攻队', '杰克·施莱尔', '弗洛伦丝·皮尤, 塞巴斯蒂安·斯坦, 朱莉娅·路易斯·德雷福斯, 刘易斯·普尔曼, 大卫·哈伯', '2025-04-30', '叶莲娜·贝洛娃、巴基·巴恩斯、红色守卫者、幽灵、模仿大师和约翰·沃克发现自己陷入了瓦伦蒂娜设置的死亡陷阱后，这些幻想破灭的弃儿必须执行一项危险的任务，这迫使他们将直面过去那些最黑暗的角落。最后他们是会分崩离析，还是会救赎自己并团结起来？', '/static/posters/雷霆特攻队_medium.jpg', 3.4, 5, 986056, 7.3, '2025-10-28 11:14:11', '2025-10-28 12:05:46');
INSERT INTO `main_film` VALUES (134, '女王神剑', 'M.J.贝塞特', '玛蒂尔达·鲁茨, 罗伯特·席安, Wallis Day, 卢卡・帕斯夸里诺, Michael Bisping', '2025-07-31', '吉尔·索洛韦(《透明家庭》系列)将取代布莱恩·辛格，执导新版[女王神剑]。本片由千禧年影业打造，索洛韦同时负责撰写新版剧本。原著漫画上世纪70年开始发行，直至今日仍在连载中。1985年版的电影版[女王神剑]围绕拥有神力、一心为家族复仇的女战士索尼娅展开。新版的选角现已正式启动。', '/static/posters/女王神剑_medium.jpg', 4, 1, 13494, 5.723, '2025-10-28 11:14:11', '2025-10-28 11:59:40');
INSERT INTO `main_film` VALUES (135, '阿兹特克蝙蝠侠：帝国冲突', 'Juan Jose Meza-Leon', '奥拉西奥·加西亚·罗哈斯, 阿尔瓦罗·莫奇, 奥马尔·查帕罗, 温贝托·布斯托, Jorge R. Gutierrez', '2025-09-18', '这部影片大胆重塑了蝙蝠侠的传奇故事，背景设定在阿兹特克帝国。一位年轻的阿兹特克男孩在父亲被西班牙征服者杀害后逃往特诺奇蒂特兰。他在蝙蝠神 Tzinacan 的神庙中训练，并研制武器为父复仇。一路上，他遇到了一些为人熟知的人物，比如美洲豹女侠和征服者埃尔南·科尔特斯。', '/static/posters/阿兹特克蝙蝠侠：帝国冲突_medium.jpg', 4, 2, 987400, 7.82, '2025-10-28 11:14:12', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (136, '她行走于黑暗中', 'Agustín Díaz Yanes', 'Susana Abaitua, Andrés Gertrúdix, Iraia Elias, 艾妮安娜·姬儿, 劳尔·阿雷瓦洛', '2025-10-03', '影片灵感源自对埃塔组织最重要的一次卧底行动，这次行动成为西班牙反恐斗争的转折点。该片以20世纪90年代至21世纪初为背景，讲述了年轻的国民警卫队女警阿马娅在恐怖组织内部卧底十余年，寻找隐藏在法国南部的秘密武器库的故事。', '/static/posters/她行走于黑暗中_medium.jpg', 6.764, 53, 1275151, 6.764, '2025-10-28 11:14:13', '2025-10-28 11:17:19');
INSERT INTO `main_film` VALUES (137, '超人总动员', '布拉德·伯德', '克雷格·西奥多·尼尔森, 霍莉·亨特, 莎拉·沃威尔, 斯宾塞·福克斯, 杰森·李', '2004-11-05', '鲍勃是一个超人特工，他惩恶扬善，深受街坊邻里的爱戴。"不可思议"先生就是他的光荣外号。他和另一个超人特工"弹力女超人"相爱，两人结婚后过上平静的生活。15年过去了，鲍勃已经像普通人一样生活，当上了保险公司的理赔员。然而他心中还是有着技痒之时。当他知道有发明家要展开攻击超人特工队、毁灭人类的计划，鲍勃终于按捺不住了。他要重出江湖，挽救人类护卫地球。但中年的超人已经大腹便便，他和敌人的斗争充满了悬念。鲍勃的妻子也跟丈夫一起投入到这场艰巨的战争中。', '/static/posters/超人总动员_medium.jpg', 3.8, 4, 9806, 7.719, '2025-10-28 11:14:13', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (138, '功夫梦：融合之道', '乔纳森·恩特威斯尔', '成龙, 王班, 乔舒亚·杰克逊, 赛迪·斯坦利, 温明娜', '2025-05-08', '功夫少年李峰（王班 饰）初入纽约，因帮朋友解围反遭当地空手道冠军"美式霸凌"，便决心参加空手道大赛赢回尊重。昔日恩师韩师傅（成龙 饰）远渡重洋携空手道大师丹尼尔（拉尔夫·马基奥 饰）出手相助，将纽约化成训练场对李峰开启宗师特训。在师傅们的教导下，李峰能否将两个武术流派融会贯通，用胜利赢得尊重并开辟属于自己的武学之道？', '/static/posters/功夫梦：融合之道_medium.jpg', 2.5, 2, 1011477, 7.101, '2025-10-28 11:14:13', '2025-10-28 11:59:38');
INSERT INTO `main_film` VALUES (139, '365 dni: Ten dzień', 'Barbara Białowąs, Tomasz Mandes', '安娜·玛丽亚·西克拉克, 米凯莱·莫罗尼, 西蒙·苏西纳, Magdalena Lamparska, Otar Saralidze', '2022-04-26', '劳拉和马西莫归来，而且比以往任何时候都要热辣。这对情侣久别重逢，但两人的新开始却因马西莫的家庭关系和一名神秘男子而变得十分复杂。为进入劳拉的生活以获取她的芳心和信任，这个神秘男子将不惜一切代价。', '/static/posters/365_dni__Ten_dzień_medium.jpg', 4.5, 2, 829557, 5.9, '2025-10-28 11:14:14', '2025-10-28 12:05:35');
INSERT INTO `main_film` VALUES (140, '复活她', 'Danny Philippou, Michael Philippou', 'Billy Barrett, 莎莉·霍金斯, Mischa Heywood, Jonah Wren Phillips, Stephen Phillips', '2025-05-28', '本片讲述了一对兄妹在他们新寄养母亲的偏远住所中，发现了一个令人毛骨悚然的邪恶仪式的故事。', '/static/posters/复活她_medium.jpg', 2, 2, 1151031, 7.413, '2025-10-28 11:14:14', '2025-10-28 11:59:36');
INSERT INTO `main_film` VALUES (141, '保养提醒', 'Lacey Uhlemeyer', '玛德莱娜·佩切, 雅各布·西皮奥, 凯蒂·M·奥布莱恩, 麦迪逊·贝利, Matteo Lane', '2025-10-07', '查莉被迫重新评估她的全女性机修店，无意中向她的网络知己博尔倾诉了心事。结果发现，博尔竟然是她现实生活中的商业竞争对手，她们的关系在职业竞争中如花绽放。', '/static/posters/保养提醒_medium.jpg', 2, 1, 1352755, 5.687, '2025-10-28 11:14:15', '2025-10-28 12:05:34');
INSERT INTO `main_film` VALUES (142, '罗拉的玩具', 'Joseph W. Sarno', 'Mary Mendum, Eric Edwards, Cathja Graff, Anita Ericsson, Anita Redling', '1975-01-01', '考古学家 Walter 和他的妻子 Laura 在瑞典的一个海岛上考古。一天妻子 Laura 发现丈夫和她的助手 Anna 在偷情。Laura 决定报复，她打电话喊来了自己以前的同性女友 Hanni……', '/static/posters/罗拉的玩具_medium.jpg', 3, 3, 81467, 4.824, '2025-10-28 11:14:16', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (143, '罪人', '瑞恩·库格勒', '迈克尔·B·乔丹, 海莉·斯坦菲尔德, 迈尔斯·卡顿, 杰克·奥康奈尔, 乌米·马萨库', '2025-04-16', '魅力冷峻且坚毅的双胞胎企业家斯莫克（迈克尔·B·乔丹 饰）和斯塔克（迈克尔·B·乔丹 饰），这对兄弟在历经第一次世界大战的战壕和芝加哥黑帮的洗礼后，于1932年带着大把现金、一卡车烈酒，怀揣着开一家自动点唱机酒吧的计划，在阔别七年后回到了他们位于密西西比三角洲的家乡克拉克斯代尔。他们穿着时髦的大城市服装，打扮得整洁利落，在这个极度贫穷、实行种族隔离的种植园小镇上显得格外扎眼。他们从汗流浃背的老好人霍格伍德（大卫·马尔多纳多 饰）手中买下了一座废弃的磨坊、里面的设备以及磨坊所在的土地，并警告霍格伍德和他三K党那帮狐朋狗友，除非他们想挨枪子，否则别踏进自己的地盘。', '/static/posters/罪人_medium.jpg', 3, 2, 1233413, 7.513, '2025-10-28 11:14:16', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (144, '铁血战士：杀戮之地', '丹·特拉亨伯格', '艾丽·范宁, 迪米特里乌斯·科罗马坦基, Michael Homick', '2025-11-05', '一名外星猎手被所属部族驱逐后，意外与一台受损的机器人结为盟友，随后踏上险象环生的旅程，寻找自己的终极宿敌。', '/static/posters/铁血战士：杀戮之地_medium.jpg', 5, 1, 1242898, 0, '2025-10-28 11:14:16', '2025-10-28 11:59:41');
INSERT INTO `main_film` VALUES (145, 'Un paseo por el Borne', 'Nick Igea', '鲁道夫·桑丘, Tábata Cerezo, 娜塔丽娅·贝尔韦克, Ruth Gabriel, Roque Ruiz', '2024-07-25', '', '/static/posters/Un_paseo_por_el_Borne_medium.jpg', 5, 1, 1130044, 0, '2025-10-28 11:14:17', '2025-10-28 12:05:33');
INSERT INTO `main_film` VALUES (146, '指环王1：护戒使者', '彼得·杰克逊', '伊利亚·伍德, 伊恩·麦克莱恩, 维果·莫特森, 西恩·奥斯汀, 伊恩·霍姆', '2001-12-18', '在古老的中土世界，一个名叫佛罗多·巴金斯的年轻人无意中得到了一枚魔戒。 这只戒指拥有无穷的神秘力量，戒指原本是黑暗君王索隆所有的，却意外地到了佛罗多手里。弗罗多决定将戒指摧毁，以免索隆夺回去巩固自己的势力。索隆为了阻止佛罗多，派出了手下的奥克斯加以追杀，一场正邪大战眼看着一触即发。', '/static/posters/指环王1：护戒使者_medium.jpg', 2.5, 2, 120, 8.425, '2025-10-28 11:14:18', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (147, '阿凡达', '詹姆斯·卡梅隆', '萨姆·沃辛顿, 佐伊·索尔达娜, 西格妮·韦弗, 史蒂芬·朗, 米歇尔·罗德里格兹', '2009-12-15', '战斗中负伤而下身瘫痪的前海军战士杰克·萨利（萨姆·沃辛顿 Sam Worthington 饰）决定替死去的同胞哥哥来到潘多拉星操纵格蕾丝博士（西格妮·韦弗 Sigourney Weaver 饰）用人类基因与当地纳美部族基因结合创造出的 "阿凡达" 混血生物。杰克的目的是打入纳美部落，外交说服他们自愿离开世代居住的家园，从而SecFor公司可砍伐殆尽该地区的原始森林，开采地下昂贵的"不可得"矿。在探索潘多拉星的过程中，杰克遇到了纳美部落的公主娜蒂瑞（佐伊·索尔达娜 Zoe Saldana 饰），向她学习了纳美人的生存技能与对待自然的态度。与此同时，SecFor 公司的经理和军方代表上校迈尔斯（史蒂芬·朗 Stephen Lang 饰）逐渐丧失耐心，决定诉诸武力驱赶纳美人……', '/static/posters/阿凡达_medium.jpg', 3, 1, 19995, 7.594, '2025-10-28 11:14:18', '2025-10-28 11:59:42');
INSERT INTO `main_film` VALUES (148, '之后', 'Jenny Gage', '约瑟芬·兰福德, 赫洛·费因斯-提芬, Shane Paul McGhie, Khadijha Red Thunder, 迪伦·阿诺德', '2019-04-11', '泰莎 是一位向来循规蹈矩的女生，在父母眼里，她是听话乖巧的好女儿，在男友眼里，她是体贴懂事的好女友，在老师眼里，她是守规矩讲礼貌的好学生，这样一个女孩，在她踏进大学校园后，邂逅了名为哈丁 的男孩。 哈丁和泰莎所见过的所有男生都不一样，他有着桀骜不驯的眼神，花哨夸张的外表，做事情也向来不拘一格。泰莎对哈丁的第一印象并不好，但随着时间的推移，他身上某些独特的气质渐渐的吸引了泰莎，她开始渴望成为像他一样自由的人。在阴差阳错之中，泰莎和哈丁接吻了，之后哈丁飘忽不定的态度反而让泰莎对他更加的沉迷。', '/static/posters/之后_medium.jpg', 3.2, 6, 537915, 7.114, '2025-10-28 11:14:20', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (149, '惊变28年', '丹尼·博伊尔', '朱迪·科默, Alfie Williams, 亚伦·泰勒-约翰逊, 拉尔夫·费因斯, 艾德文·瑞丁', '2025-06-18', '距离 rage 病毒从生物武器实验室泄漏已过去 28 年，如今这片土地仍处于残酷的封锁隔离中，但有些人已在感染者盘踞的世界里找到了生存之道。其中一支队伍栖息在一座小岛上，仅有一条重兵把守的堤道与大陆相连。当一名成员奉命深入大陆腹地执行任务时，他发现了诸多秘密、奇观与骇人真相 —— 病毒不仅使感染者发生变异，也改变了其他幸存者的生存形态。', '/static/posters/惊变28年_medium.jpg', 4.3, 3, 1100988, 6.673, '2025-10-28 11:14:20', '2025-10-28 12:05:34');
INSERT INTO `main_film` VALUES (150, '神偷奶爸4', '克里斯·雷纳德', '史蒂夫·加瑞尔, 克丽丝滕·威格, 威尔·法瑞尔, 索菲亚·维加拉, 米兰达·卡斯格拉夫', '2024-06-20', '格鲁（史蒂夫·卡瑞尔 Steve Carell 配音）和露西（克里斯汀·韦格 Kristen Wiig 配音）一家即将展开家庭生活的新篇章，迎接新成员"迷你格鲁"，而这个小宝宝也会用尽方法折磨格鲁这个新手老爸。新反派恶霸麦斯（威尔·法瑞尔 Will Ferrell 配音）和他既致命危险又美丽性感的女友华伦天娜（索菲娅·维加拉 Sofía Vergara 配音）来势汹汹，格鲁一家面临未知危险。此时，全新超级小黄人重磅亮相，成为帮助格鲁一家度过这次危机的"秘密武器"。一场惊险刺激、笑料百出的全新冒险即将展开。', '/static/posters/神偷奶爸4_medium.jpg', 5, 3, 519182, 7.014, '2025-10-28 11:14:20', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (151, '招魂', '温子仁', '维拉·法米加, 帕特里克·威尔森, 朗·里维斯顿, 莉莉·泰勒, 乔伊·金', '2013-07-18', '二十世纪七十年代，罗杰与卡罗琳两夫妇带着他们五个可爱美丽的女儿，搬到了位于罗德岛哈瑞斯维尔的一幢旧宅居住。房屋虽然古旧沧桑，历史悠久，但是却让佩隆一家体会到回归田园的快乐与喜悦。谁知好景不长，接二连三的怪异事件相继出现，令女孩们惊声尖叫，也让佩隆夫妇的神经绷到极点。为此，他们辗转找到当时最负盛名的沃伦夫妇。', '/static/posters/招魂_medium.jpg', 3.5, 4, 138843, 7.54, '2025-10-28 11:14:21', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (152, 'Život k sežrání', 'Kristina Dufková', 'Hugo Kovács, Tatiana Dyková, David Novotný, Eliška Křenková, Jiří Bartoška', '2024-10-17', '', '/static/posters/Život_k_sežrání_medium.jpg', 3.3, 3, 947512, 6.125, '2025-10-28 11:14:21', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (153, 'थामा', 'Aditya Sarpotdar', '阿尤斯曼·库拉纳, 拉什米卡·曼丹娜, 纳瓦祖丁·西迪基, Paresh Rawal, Faisal Malik', '2025-10-21', '', '/static/posters/थामा_medium.jpg', 6.6, 6, 1196364, 6.6, '2025-10-28 11:14:22', '2025-10-28 11:17:00');
INSERT INTO `main_film` VALUES (154, '生不如死', 'R. Ellis Frazier', '汤姆·贝伦杰, 麦可·杰·怀特, 路易斯·曼迪勒, Gillian White, 迈克尔·科彭', '2022-12-16', '布莱恩（迈克尔·杰·怀特 Michael Jai White 饰），一个有着神秘过去的男人，来到墨西哥边境的小镇，希望重新开始并过着简单的生活。在这里，他遇到了米格尔，一位刚失去母亲的失意少年，但他却被当地黑帮盯上。布莱恩起初并无意愿，但最终还是用武术引导米格尔走上正途，成为他的导师，甚至是父亲般的存在。随着故事的展开，揭露布莱恩并非只是一个想过平凡生活的男人。他背负着复杂、暴力的过去，一直努力摆脱。但当他的过去找上门来，他被迫陷入一场生死搏斗，试图洗清自己的罪名，拯救米格尔，以及夺回他所失去的一切。', '/static/posters/生不如死_medium.jpg', 2, 2, 1028248, 6.227, '2025-10-28 11:14:22', '2025-10-28 12:05:38');
INSERT INTO `main_film` VALUES (155, '疯狂动物城2', '贾里德·布什, 拜恩·霍华德', '詹妮弗·古德温, 杰森·贝特曼, 关继威, 福琼·费姆斯特, 安迪·萨姆伯格', '2025-11-26', '《疯狂动物城2》将确认朱迪和尼克的关系，导演暗示二人组可以不仅仅是朋友。', '/static/posters/疯狂动物城2_medium.jpg', 3, 1, 1084242, 0, '2025-10-28 11:14:23', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (156, 'St. Patrick\'s Day Massacre', 'Steve Lawson', 'Marta Svetek, Ayvianna Snow, Ben Manning, Charlie Bond, Ciaron Davies', '2025-03-10', '', '/static/posters/St._Patrick\'s_Day_Massacre_medium.jpg', 3, 1, 1377413, 4.667, '2025-10-28 11:14:23', '2025-10-28 12:05:35');
INSERT INTO `main_film` VALUES (157, '同甘共苦', '迈克尔·山克斯', '戴夫·弗兰科, 艾莉森·布里, 达蒙·海瑞曼, Mia Morrissey, Karl Richmond', '2025-07-28', '多年情侣蒂姆（戴夫·弗兰科 Dave Franco 饰）和米莉（爱丽森·布里 Alison Brie 饰）厌倦了城市生活，决定搬到乡下，试图过上自给自足的田园生活。他们很快发现，这种生活比他们想象的更加艰难，也更加考验他们的关系。', '/static/posters/同甘共苦_medium.jpg', 3.5, 2, 1303714, 5.9, '2025-10-28 11:14:24', '2025-10-28 12:05:40');
INSERT INTO `main_film` VALUES (158, 'The Wasp', 'Chris Sun', 'Sisi Stringer, Annabelle Stephenson, 瑞安·科雷尔, Don Bridges, 约翰·贾瑞特', '2025-04-17', '', '/static/posters/The_Wasp_medium.jpg', 2.5, 2, 1222731, 5.6, '2025-10-28 11:14:24', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (159, 'In the Blink of an Eye', 'Andrew Stanton', '凯特·布兰切特, 大卫·奥伊罗, 文·瑞姆斯, 凯文·波拉克, 拉什达·琼斯', '2025-10-09', '当一场灾难性的太阳耀斑导致地球上所有人类消失时，一位电影导演（凯特·布兰切特 饰）和一位电影剪辑师（大卫·奥伊罗 饰）被困在时间循环中，被迫一遍又一遍地重演他们在地球上的最后一天。', '/static/posters/In_the_Blink_of_an_Eye_medium.jpg', 3, 3, 1072656, 6.6, '2025-10-28 11:14:25', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (160, 'Kill the Babysitter', 'Ryan Kruger', 'Megan du Plessis, 史蒂夫·沃尔, 马克·埃尔德金, 塔尼娅·范·格拉恩, 萨曼莎·洛伦', '2025-10-09', '一位保姆在照顾孩子时发现房主与撒旦教徒有联系，她必须与时间赛跑，在房主回家前带着孩子逃离这所房子。', '/static/posters/Kill_the_Babysitter_medium.jpg', 3, 1, 1511476, 5.5, '2025-10-28 11:14:25', '2025-10-28 11:59:38');
INSERT INTO `main_film` VALUES (161, 'The Uninvited', 'Shana Betz', '布丽特妮·罗伯森, 斯科特·斯比德曼, 克里斯·迪亚曼托普洛斯, 阿纳斯塔西娅·巴拉诺娃, 阿利维亚·阿林·林德', '2025-10-08', '一位父亲带着他的女儿们搬进了一座偏远的老宅，试图从一场可怕的悲剧中恢复过来。然而，这座房子隐藏着一个可怕的秘密，迫使这个家庭为了生存而战斗。', '/static/posters/The_Uninvited_medium.jpg', 2.5, 2, 1417852, 6.8, '2025-10-28 11:14:25', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (162, 'The White Raven', 'Justin Lee', '肖恩·派特里克·弗兰纳里, 米歇尔·范, 爱德华·弗朗, 凯文·盖奇, 迈克尔·帕尔', '2025-10-15', '一位名叫阿瓦隆的年轻女子在父亲去世后回到她童年的家，却发现一个神秘的邪教组织已经接管了这个小镇，并计划将小镇居民献祭给一个古老的恶魔。', '/static/posters/The_White_Raven_medium.jpg', 3, 2, 1522745, 6.5, '2025-10-28 11:14:26', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (163, 'The Last Girl', 'David M. Parks', '阿比盖尔·布雷斯林, 尼尔·麦克唐纳, 迪恩·凯恩, 汤姆·塞兹摩尔, 迈克尔·马德森', '2025-10-22', '一位年轻女子在末日后的世界中生存，她必须保护自己免受一群危险的掠夺者的伤害，同时寻找其他幸存者。', '/static/posters/The_Last_Girl_medium.jpg', 3.5, 2, 1537891, 6.2, '2025-10-28 11:14:26', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (164, 'The Devil\'s Playground', 'John R. Leonetti', '维多利亚·嘉丝蒂, 钱斯·赫斯菲尔德, 麦迪森·伊瑟曼, 莉亚·玛瑞·约翰逊, 罗比·阿美尔', '2025-10-29', '一群青少年在万圣节之夜闯入了一个废弃的游乐场，却不知道这个游乐场是一个恶魔的领地，他们必须想办法在恶魔抓住他们之前逃脱。', '/static/posters/The_Devil\'s_Playground_medium.jpg', 3, 1, 1549012, 6.8, '2025-10-28 11:14:27', '2025-10-28 12:05:39');
INSERT INTO `main_film` VALUES (165, 'The Curse of the Mummy', 'Dario Piana', '奥利维亚·库克, 卢克·罗伯茨, 拉尔夫·伊内森, 霍纳·妮芙芮, 詹姆斯·科兹莫', '2025-11-05', '一群考古学家在埃及发现了一个被诅咒的木乃伊，当他们不小心唤醒它时，他们必须与时间赛跑，在木乃伊杀死他们所有人之前找到阻止它的方法。', '/static/posters/The_Curse_of_the_Mummy_medium.jpg', 3.2, 5, 1556789, 6.5, '2025-10-28 11:14:27', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (166, 'The Haunting of Hill House', '迈克·弗拉纳根', '维多利亚·佩德雷蒂, 奥利弗·杰森-科恩, 凯特·西格尔, 米契尔·哈思曼, 卡拉·古奇诺', '2018-10-12', '兄弟姐妹们在童年时期在希尔山庄长大，这座山庄后来成为美国最著名的鬼屋之一。成年后，悲剧迫使他们最终面对过去的鬼魂，其中一些鬼魂潜伏在他们的心中，而另一些鬼魂则潜伏在臭名昭著的希尔山庄的阴影中。', '/static/posters/The_Haunting_of_Hill_House_medium.jpg', 3.8, 4, 67633, 8.6, '2025-10-28 11:14:28', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (167, 'The Conjuring: The Devil Made Me Do It', '迈克尔·查韦斯', '维拉·法米加, 帕特里克·威尔森, 鲁伯特·弗兰德, 莎拉·凯瑟琳·霍克, 朱利安·希威德', '2021-05-26', '这是埃德和洛林·沃伦档案中迄今为止最令人震惊的恐怖案件之一，从一名年轻男孩的谋杀案审判开始，这是美国历史上首次被告声称恶魔附身作为辩护。', '/static/posters/The_Conjuring__The_Devil_Made_Me_Do_It_medium.jpg', 3.5, 2, 423108, 6.3, '2025-10-28 11:14:28', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (168, 'The Nun', '科林·哈迪', '德米安·比齐尔, 泰莎·法米加, 乔纳斯·布洛凯, 邦妮·阿伦斯, 夏洛特·霍普', '2018-09-05', '一名修女在罗马尼亚一座与世隔绝的修道院中自杀后，梵蒂冈派出一名有洞察力的神父和一名即将宣誓成为修女的见习修女去调查。他们一起揭开了这个邪恶的秘密。冒着生命和灵魂的危险，他们与一股邪恶的力量面对面，这股力量以恶魔修女的形式使修道院变成了恐怖的战场。', '/static/posters/The_Nun_medium.jpg', 3, 2, 439079, 5.3, '2025-10-28 11:14:29', '2025-10-28 12:05:44');
INSERT INTO `main_film` VALUES (169, 'Annabelle: Creation', '大卫·F·桑德伯格', '安东尼·拉帕格利亚, 米兰达·奥图, 塔拉吉·P·汉森, 卢卢·威尔逊, 斯蒂芬妮·西格曼', '2017-08-03', '多年后，一个玩偶制造商和他的妻子在失去女儿后，好心收留了一个修女和几个被安置在那里的女孩，却成了恶魔玩偶安娜贝尔的目标。', '/static/posters/Annabelle__Creation_medium.jpg', 3.7, 3, 442249, 6.5, '2025-10-28 11:14:29', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (170, 'The Curse of La Llorona', '迈克尔·查韦斯', '琳达·卡德里尼, 雷蒙德·克鲁斯, 帕特里夏·维拉奎兹, 西恩·帕特里克·汤玛斯, 托尼·阿门多拉', '2019-04-17', '在20世纪70年代的洛杉矶，无视社会工作者警告的悲痛，一位母亲将自己的孩子置于危险的超自然实体的掌控之中。', '/static/posters/The_Curse_of_La_Llorona_medium.jpg', 3.2, 5, 483980, 5.3, '2025-10-28 11:14:30', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (171, 'The Conjuring 2', '温子仁', '维拉·法米加, 帕特里克·威尔森, 麦迪逊·沃尔夫, 弗兰西丝·奥康纳, 劳伦·埃斯波西托', '2016-06-07', '洛林和埃德·沃伦前往伦敦的恩菲尔德，帮助一位单身母亲和她的四个孩子，他们住在一栋被邪恶灵魂困扰的房子里。', '/static/posters/The_Conjuring_2_medium.jpg', 4, 1, 259693, 7.3, '2025-10-28 11:14:30', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (172, 'Annabelle', '约翰·R·莱昂内蒂', '安娜贝拉·沃丽丝, 瓦德·霍尔顿, 阿尔法·伍达德, 托尼·阿门多拉, 凯莉·奥马利', '2014-10-01', '一对新婚夫妇的家中出现了一个看似被附身的娃娃，他们很快就被一股邪恶的恐怖力量所困扰，这股力量威胁要把他们的灵魂撕成碎片。', '/static/posters/Annabelle_medium.jpg', 3.5, 2, 250546, 5.4, '2025-10-28 11:14:31', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (173, 'The Conjuring', '温子仁', '维拉·法米加, 帕特里克·威尔森, 莉莉·泰勒, 朗·里维斯顿, 乔伊·金', '2013-07-18', '超自然现象调查员埃德和洛林·沃伦受命帮助一个被黑暗灵魂困扰的家庭。为了拯救他们，沃伦夫妇将不得不为迄今为止最可怕的案件做准备。', '/static/posters/The_Conjuring_medium.jpg', 3.8, 4, 138843, 7.5, '2025-10-28 11:14:31', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (174, 'Insidious: The Red Door', '帕特里克·威尔森', '泰·辛普金斯, 帕特里克·威尔森, 萝丝·拜恩, 辛克莱尔·丹尼尔, 安德鲁·阿斯特', '2023-07-05', '为了将他们家族的恶魔抛在身后，乔希·兰伯特和大学一年级的儿子道尔顿被迫比以往任何时候都更深入"深渊"，面对他们家族黑暗的过去和一系列新的、更可怕的恐怖，这些恐怖潜伏在红色门的后面。', '/static/posters/Insidious__The_Red_Door_medium.jpg', 3.2, 5, 614479, 6, '2025-10-28 11:14:32', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (175, 'Insidious: The Last Key', '亚当·罗比特尔', '林·沙烨, 雷·沃纳尔, 安格斯·桑普森, 柯克·埃斯沃多, 凯特琳·杰拉德', '2018-01-03', '超自然专家伊莉丝·雷尼尔必须回到她在新墨西哥州的童年家园，面对她最个人化的恶魔——一个有着可怕个人联系、名叫"钥匙大师"的实体。', '/static/posters/Insidious__The_Last_Key_medium.jpg', 3.5, 2, 505948, 6.1, '2025-10-28 11:14:32', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (176, 'Insidious: Chapter 3', '雷·沃纳尔', '林·沙烨, 德蒙特·莫罗尼, 斯蒂芬妮·斯科特, 安格斯·桑普森, 雷·沃纳尔', '2015-06-04', '超自然专家伊莉丝·雷尼尔试图帮助一名青少年，这名青少年已成为一个想要入侵我们世界的邪恶实体的目标。', '/static/posters/Insidious__Chapter_3_medium.jpg', 3.7, 3, 280092, 6.1, '2025-10-28 11:14:33', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (177, 'Insidious: Chapter 2', '温子仁', '帕特里克·威尔森, 萝丝·拜恩, 林·沙烨, 芭芭拉·赫希, 泰·辛普金斯', '2013-09-12', '兰伯特一家试图揭开他们家中困扰他们的黑暗秘密，却发现他们的麻烦远未结束，他们的命运与一个超越这个世界的地方联系在一起。', '/static/posters/Insidious__Chapter_2_medium.jpg', 3.8, 4, 91586, 6.6, '2025-10-28 11:14:33', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (178, 'Insidious', '温子仁', '帕特里克·威尔森, 萝丝·拜恩, 泰·辛普金斯, 林·沙烨, 芭芭拉·赫希', '2010-09-13', '一对夫妇的儿子神秘地陷入昏迷，成为通往另一个世界的通道后，他们拼命地寻找帮助。', '/static/posters/Insidious_medium.jpg', 3.5, 2, 49018, 6.8, '2025-10-28 11:14:34', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (179, 'The Black Phone', '斯科特·德里克森', '梅森·泰晤士, 玛德琳·麦格劳, 伊桑·霍克, 杰瑞米·戴维斯, E·罗杰·米切尔', '2021-06-24', '13岁的天才少年芬尼被一个变态杀手绑架，并被关在一个隔音的地下室里，每当墙上的黑色电话响起时，他都能听到之前受害者的声音。', '/static/posters/The_Black_Phone_medium.jpg', 3.8, 4, 756999, 7, '2025-10-28 11:14:34', '2025-10-28 12:05:42');
INSERT INTO `main_film` VALUES (180, 'Sinister', '斯科特·德里克森', '伊桑·霍克, 文森特·多诺费奥, 詹姆斯·兰索恩, 弗雷德·多尔顿·汤普森, 克莱尔·弗利', '2012-10-11', '一名真实犯罪作家发现了一盒家庭暴力电影，这些电影使他的家人成为超自然实体的目标。', '/static/posters/Sinister_medium.jpg', 3.7, 3, 82507, 6.8, '2025-10-28 11:14:35', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (181, 'The Exorcism of Emily Rose', '斯科特·德里克森', '劳拉·琳妮, 汤姆·威尔金森, 詹妮弗·卡朋特, 坎贝尔·斯科特, 科尔姆·费奥瑞', '2005-09-08', '一位牧师因一名年轻大学生的死亡而受审，据称她在一次驱魔仪式中死亡。', '/static/posters/The_Exorcism_of_Emily_Rose_medium.jpg', 3.5, 2, 3933, 6.7, '2025-10-28 11:14:35', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (182, 'Deliver Us from Evil', '斯科特·德里克森', '埃里克·巴纳, 埃德加·拉米雷兹, 奥立薇娅·玛恩, 肖恩·哈里斯, 乔尔·麦克哈尔', '2014-07-01', '一名纽约警察局警官调查了一系列与超自然力量有关的令人不安且无法解释的犯罪事件。', '/static/posters/Deliver_Us_from_Evil_medium.jpg', 3.2, 5, 241554, 6.2, '2025-10-28 11:14:36', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (183, 'The Day the Earth Stood Still', '斯科特·德里克森', '基努·里维斯, 詹妮弗·康纳利, 凯西·贝茨, 贾登·史密斯, 约翰·克立斯', '2008-12-11', '一个外星人和一个巨大的机器人降落在地球上，向人类发出停止暴力活动的最后通牒，否则将面临毁灭。', '/static/posters/The_Day_the_Earth_Stood_Still_medium.jpg', 3, 1, 86331, 5.5, '2025-10-28 11:14:36', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (184, 'Hellraiser', '大卫·布鲁克纳', '欧迪·费瑟, 杰米·克莱顿, 高兰·维斯耶克, 布兰登·弗林, 德鲁·斯塔基', '2022-10-05', '一名年轻女子与成瘾作斗争，她意外地得到了一个神秘的盒子，这个盒子承诺给她带来终极的快感，但却让她与一群来自另一个维度的超自然生物——哀悼者发生了冲突。', '/static/posters/Hellraiser_medium.jpg', 3.7, 3, 664469, 6.1, '2025-10-28 11:14:37', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (185, 'The Night House', '大卫·布鲁克纳', '丽贝卡·豪尔, 萨拉·古德伯格, 沃迪·科蒂斯·霍尔, 伊万·乔尼凯特, 斯塔西·马汀', '2020-01-24', '一名寡妇开始发现她已故丈夫令人不安的秘密。', '/static/posters/The_Night_House_medium.jpg', 3.5, 2, 588228, 6.5, '2025-10-28 11:14:37', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (186, 'The Ritual', '大卫·布鲁克纳', '拉菲·斯波, 阿舍尔·阿里, 罗伯·詹姆斯-克里尔, 山姆·特劳顿, 保罗·雷德', '2017-10-11', '在瑞典徒步旅行时，一群大学老朋友遇到了一股古老邪恶的力量，这股力量在他们最黑暗的恐惧中追杀他们。', '/static/posters/The_Ritual_medium.jpg', 3.8, 4, 433422, 6.3, '2025-10-28 11:14:38', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (187, 'The Empty Man', '大卫·普瑞尔', '詹姆斯·戴尔, 马琳·爱尔兰, 萨沙·弗若洛娃, 罗恩·坎纳达, 斯蒂芬·鲁特', '2020-10-22', '一名前警察在调查一名失踪少女的案件时，发现了一个秘密社团和一个危险的超自然实体。', '/static/posters/The_Empty_Man_medium.jpg', 3.2, 5, 535292, 6.2, '2025-10-28 11:14:38', '2025-10-28 12:05:41');
INSERT INTO `main_film` VALUES (188, 'The Dark and the Wicked', '布莱恩·伯蒂诺', '马林·爱尔兰, 迈克尔·阿伯特, 朱莉·奥利弗-图克斯通, 琳恩·安德鲁斯, 汤姆·诺兰', '2020-08-06', '一对兄弟姐妹回到他们童年的农场帮助垂死的父亲，却发现一股邪恶的存在正在吞噬他们的家庭。', '/static/posters/The_Dark_and_the_Wicked_medium.jpg', 3.7, 3, 778810, 6.3, '2025-10-28 11:14:39', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (189, 'The Strangers: Prey at Night', '约翰内斯·罗伯茨', '克里斯蒂娜·亨德里克斯, 马丁·亨德森, 拜莉·麦迪逊, 刘易斯·普尔曼, 艾玛·贝洛米', '2018-03-08', '一个家庭在一个与世隔绝的拖车公园里成为三个蒙面杀手的目标。', '/static/posters/The_Strangers__Prey_at_Night_medium.jpg', 3.5, 2, 433422, 5.3, '2025-10-28 11:14:39', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (190, 'The Strangers', '布莱恩·伯蒂诺', '丽芙·泰勒, 斯科特·斯比德曼, 格伦·豪尔顿, 嘉玛·沃德, 基拉·桑切斯', '2008-05-29', '一对夫妇在偏远的度假屋中被三个蒙面陌生人恐吓。', '/static/posters/The_Strangers_medium.jpg', 3.8, 4, 8326, 6.1, '2025-10-28 11:14:40', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (191, 'The Witch', '罗伯特·艾格斯', '安雅·泰勒-乔伊, 拉尔夫·伊内森, 凯特·迪基, 哈维·斯克林肖, 艾丽·格兰杰', '2015-01-27', '17世纪30年代的新英格兰，一个虔诚的基督徒家庭在森林边缘与世隔绝地生活，当他们的新生儿神秘失踪时，这个家庭开始分崩离析。', '/static/posters/The_Witch_medium.jpg', 3.7, 3, 310131, 6.9, '2025-10-28 11:14:40', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (192, 'The Lighthouse', '罗伯特·艾格斯', '威廉·达福, 罗伯特·帕丁森, 瓦莱丽娅·卡拉曼, 洛根·霍克斯', '2019-05-18', '19世纪90年代，两名灯塔看守人试图在偏远的、神秘的新英格兰岛屿上保持理智。', '/static/posters/The_Lighthouse_medium.jpg', 3.8, 4, 503919, 7.5, '2025-10-28 11:14:41', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (193, 'The Northman', '罗伯特·艾格斯', '亚历山大·斯卡斯加德, 妮可·基德曼, 克拉斯·邦, 安雅·泰勒-乔伊, 古斯塔夫·林德', '2022-04-15', '一名北欧王子在父亲被谋杀后踏上复仇之路。', '/static/posters/The_Northman_medium.jpg', 3.7, 3, 639933, 7.1, '2025-10-28 11:14:41', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (194, 'Midsommar', '阿里·艾斯特', '弗洛伦丝·皮尤, 杰克·莱诺, 威尔·保尔特, 威廉·杰克森·哈珀, 维尔赫尔姆·布洛姆根', '2019-07-03', '一对夫妇前往瑞典参加一个只在仲夏举行的节日，却发现这个节日的东道主是一个邪教。', '/static/posters/Midsommar_medium.jpg', 3.8, 4, 530385, 7.1, '2025-10-28 11:14:42', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (195, 'Hereditary', '阿里·艾斯特', '托妮·科莱特, 加布里埃尔·伯恩, 亚历克斯·沃尔夫, 米莉·夏普洛, 安·唐德', '2018-06-07', '一个家庭在祖母去世后开始解开可怕的秘密。', '/static/posters/Hereditary_medium.jpg', 3.7, 3, 493922, 7.3, '2025-10-28 11:14:42', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (196, 'The Babadook', '詹妮弗·肯特', '埃茜·戴维斯, 诺亚·怀斯曼, 丹尼尔·亨绍尔, 海莉·麦克尔海尼, 芭芭拉·韦斯特', '2014-05-22', '一名单身母亲和她的儿子被一本名为"巴巴杜克先生"的儿童绘本中的邪恶实体恐吓。', '/static/posters/The_Babadook_medium.jpg', 3.8, 4, 242224, 6.8, '2025-10-28 11:14:43', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (197, 'The Nightingale', '詹妮弗·肯特', '艾斯琳·弗兰乔茜, 山姆·克拉弗林, 贝姆·杰梅因, 达蒙·海瑞曼, 哈里·格林伍德', '2018-09-02', '1825年，一名年轻的爱尔兰囚犯在塔斯马尼亚荒野中追捕一名英国士兵，为她的家人报仇。', '/static/posters/The_Nightingale_medium.jpg', 3.7, 3, 503919, 7.2, '2025-10-28 11:14:43', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (198, 'The Invitation', '卡瑞恩·库萨马', '罗根·马歇尔-格林, 坦米·布兰查德, 米希尔·赫伊斯曼, 伊梅雅格特伊·科伦尼伊乐迪, 琳赛·柏奇', '2015-03-13', '一名男子在洛杉矶参加晚宴时，开始怀疑前妻和她的新丈夫有险恶的意图。', '/static/posters/The_Invitation_medium.jpg', 3.5, 2, 289027, 6.6, '2025-10-28 11:14:44', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (199, 'The Loved Ones', '肖恩·伯恩', '罗宾·麦克利维, 泽维尔·塞缪尔, 约翰·布鲁普顿, 理查德·威尔逊, 杰西卡·麦克纳米', '2009-09-13', '一名青少年拒绝了一名同学参加舞会的邀请，结果被她和她精神错乱的父亲绑架并折磨。', '/static/posters/The_Loved_Ones_medium.jpg', 3.7, 3, 42888, 6.7, '2025-10-28 11:14:44', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (200, 'The Descent', '尼尔·马歇尔', '肖娜·麦克唐纳, 娜塔莉·杰克逊·门多萨, 亚历克斯·瑞德, 萨斯基亚·马尔德, 米亚娜·伯宁', '2005-07-08', '一名女子和她的朋友们在阿巴拉契亚山脉探险时，被困在一个未被发现的洞穴系统中，并成为一群进化生物的食物。', '/static/posters/The_Descent_medium.jpg', 3.8, 4, 15373, 7.2, '2025-10-28 11:14:45', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (201, 'Dog Soldiers', '尼尔·马歇尔', '肖恩·帕特维, 凯文·麦克基德, 利亚姆·坎宁安, 托马斯·洛克耶, 达伦·莫菲特', '2002-05-10', '一支英国陆军小队在苏格兰高地进行训练演习时，遭到一群狼人的攻击。', '/static/posters/Dog_Soldiers_medium.jpg', 3.7, 3, 10878, 6.8, '2025-10-28 11:14:45', '2025-10-28 12:05:43');
INSERT INTO `main_film` VALUES (202, 'The Mist', '弗兰克·德拉邦特', '托马斯·简, 马西娅·盖伊·哈登, 劳瑞·侯登, 安德鲁·布劳尔, 托比·琼斯', '2007-11-21', '一场奇怪的暴风雨过后，一股神秘的迷雾笼罩了一个小镇，将一群购物者困在超市里，并与隐藏在迷雾中的可怕生物作斗争。', '/static/posters/The_Mist_medium.jpg', 3.8, 4, 7874, 7.1, '2025-10-28 11:14:46', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (203, 'The Shawshank Redemption', '弗兰克·德拉邦特', '蒂姆·罗宾斯, 摩根·弗里曼, 鲍勃·冈顿, 詹姆斯·惠特摩, 吉尔·贝罗斯', '1994-09-22', '两名被监禁的男子在多年间建立了友谊，通过共同的善行和赎罪行为找到了慰藉和最终的救赎。', '/static/posters/The_Shawshank_Redemption_medium.jpg', 4, 1, 278, 9.3, '2025-10-28 11:14:46', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (204, 'The Green Mile', '弗兰克·德拉邦特', '汤姆·汉克斯, 大卫·摩斯, 迈克·克拉克·邓肯, 邦尼·亨特, 詹姆斯·克伦威尔', '1999-12-10', '死囚牢房的看守与一名被指控谋杀两名年轻女孩的黑人男子建立了不寻常的关系。', '/static/posters/The_Green_Mile_medium.jpg', 3.8, 4, 497, 8.6, '2025-10-28 11:14:47', '2025-10-28 12:05:45');
INSERT INTO `main_film` VALUES (205, 'The Godfather: Part II', '弗朗西斯·科波拉', '阿尔·帕西诺, 罗伯特·杜瓦尔, 黛安·基顿, 罗伯特·德尼罗, 约翰·凯泽尔', '1974-12-12', '迈克尔·柯里昂在黑手党中巩固权力的早期统治，以及维托·柯里昂从西西里童年到1917年纽约黑帮生活建立家族企业的平行故事。', '/static/posters/The_Godfather__Part_II_medium.jpg', 4, 1, 240, 9, '2025-10-28 11:14:47', '2025-10-28 12:05:50');
INSERT INTO `main_film` VALUES (206, 'The Godfather: Part III', '弗朗西斯·科波拉', '阿尔·帕西诺, 黛安·基顿, 塔莉娅·夏尔, 安迪·加西亚, 埃里·瓦拉赫', '1990-12-24', '在企图将家族企业合法化的过程中，年迈的迈克尔·柯里昂寻求救赎，同时感到内疚，并对他的过去感到后悔。', '/static/posters/The_Godfather__Part_III_medium.jpg', 3.5, 2, 242, 7.6, '2025-10-28 11:14:48', '2025-10-28 12:05:50');
